  /// Listen in real-time for incoming WebRTC call offers addressed to the
  /// current user. This is much faster than waiting for the bulk chat_v2
  /// document to sync.
  void _startWebRTCSignalingListener() {
    _webrtcSignalingSubscription?.cancel();
    _webrtcSignalingSubscription = null;
    if (!_isCloudSyncAvailable() ||
        !_isAuthenticated ||
        _currentUser.id.trim().isEmpty) {
      return;
    }
    final authUid = _firebaseAuthUid();
    if (authUid.isEmpty) {
      return;
    }

    final query = FirebaseFirestore.instance
        .collection('porc_webrtc_signaling')
        .where('calleeId', isEqualTo: _currentUser.id)
        .where('calleeAuthUid', isEqualTo: authUid)
        .where('hangUp', isEqualTo: false);

    _webrtcSignalingSubscription = query.snapshots().listen((snapshot) {
      if (!mounted || !_isAuthenticated) return;
      for (final change in snapshot.docChanges) {
        if (change.type != DocumentChangeType.added) continue;
        final data = change.doc.data();
        if (data == null) continue;
        if (data['hangUp'] == true) continue;
        if (data['answer'] != null) continue; // already answered

        final sessionId = change.doc.id;
        // Skip if we are already handling this call.
        if (_incomingCallOffer?.sessionId == sessionId) continue;
        if (_activeCallSessionId == sessionId) continue;

        final callerId = _readString(data['callerId']).trim();
        final callerName = _readString(data['callerName']).trim();
        final callTypeRaw = _readString(data['callType']).trim();
        final callType = callTypeRaw.isEmpty ? 'audio' : callTypeRaw;
        final transportRaw = _readString(
          data['transport'],
        ).trim().toLowerCase();
        final transport = transportRaw == _callTransportLiveKit
            ? _callTransportLiveKit
            : _callTransportWebRtc;
        final roomName = _readString(data['roomName']).trim();
        final conversationId = _readString(data['conversationId']).trim();

        if (callerId.isEmpty || callerId == _currentUser.id) continue;
        if (!_isConversationVisibleForCurrentUser(conversationId)) continue;

        // Check age — ignore calls older than max age.
        final createdAt = data['createdAt'];
        if (createdAt is Timestamp) {
          final age = DateTime.now().difference(createdAt.toDate()).inMinutes;
          if (age > _incomingCallMaxAgeMinutes) continue;
        }

        setState(() {
          _incomingCallOffer = _IncomingCallOffer(
            sessionId: sessionId,
            conversationId: conversationId,
            callerId: callerId,
            callerName: callerName.isEmpty ? callerId : callerName,
            callType: callType == 'video' ? 'video' : 'audio',
            transport: transport,
            roomName: roomName,
            sentAt: createdAt is Timestamp
                ? createdAt.toDate()
                : DateTime.now(),
          );
          if (_canAccessTab(AppTabs.messenger)) {
            _activeTab = AppTabs.messenger;
            _activeChatConversationId = conversationId;
            _isMobileMessengerThreadOpen = true;
          }
        });
        _startIncomingCallRingtone();
        _showInfo(
          'Appel ${callType == 'video' ? 'vidéo' : 'audio'} entrant: ${callerName.isEmpty ? callerId : callerName}',
        );
        break; // process only the first new incoming call
      }
    }, onError: (_) {});
  }

  void _startRealtimeChatSyncListener() {
    _chatRealtimeSubscription?.cancel();
    _chatRealtimeSubscription = null;
    if (!mounted || !_isCloudSyncAvailable()) {
      return;
    }

    try {
      _chatRealtimeSubscription = _cloudChatRealtimeRef
          .orderBy('sentAtMs', descending: true)
          .limit(_cloudChatRealtimeLimit)
          .snapshots()
          .listen(
            (snapshot) {
              if (!mounted) {
                return;
              }
              final incoming = <ChatMessage>[];
              for (final doc in snapshot.docs) {
                final map = Map<String, dynamic>.from(doc.data());
                final rawId = _readString(map['id']).trim();
                if (rawId.isEmpty) {
                  map['id'] = doc.id;
                }
                final message = _chatMessageFromJson(map);
                if (message != null) {
                  incoming.add(message);
                }
              }
              if (incoming.isEmpty) {
                return;
              }
              setState(() {
                _mergeChatMessagesInState(incoming);
              });
              _syncIncomingCallOffer();
              _persistState(pushCloud: false);
            },
            onError: (_) {
              // Keep regular sync path as fallback.
            },
          );
    } catch (_) {
      // Keep regular sync path as fallback.
    }
  }

  void _startUsersRealtimeListener() {
    _usersRealtimeSubscription?.cancel();
    _usersRealtimeSubscription = null;
    if (!mounted || !_isCloudSyncAvailable() || !_isAuthenticated) {
      return;
    }

    try {
      _usersRealtimeSubscription = _cloudUsersRef.snapshots().listen(
        (snapshot) {
          if (!mounted) {
            return;
          }
          final remoteUsers = snapshot.docs
              .map((doc) {
                final map = Map<String, dynamic>.from(doc.data());
                if (_readString(map['id']).trim().isEmpty) {
                  map['id'] = doc.id;
                }
                return _userFromJson(map);
              })
              .whereType<UserProfile>()
              .toList();
          final remoteIds = remoteUsers
              .map((user) => user.id.trim())
              .where((id) => id.isNotEmpty)
              .toSet();
          if (!_usersCollectionHydrated) {
            _usersCollectionHydrated = true;
            if (remoteUsers.isEmpty && _users.isNotEmpty) {
              for (final local in _users) {
                _pendingUserDeleteIds.remove(local.id);
                _pendingUserUpsertIds.add(local.id);
                unawaited(_upsertUserRecordToCloud(local));
              }
            }
          }
          _pendingUserUpsertIds.removeWhere(remoteIds.contains);
          _pendingUserDeleteIds.removeWhere((id) => !remoteIds.contains(id));
          final pendingLocalUsers = _users
              .where(
                (user) =>
                    _pendingUserUpsertIds.contains(user.id) &&
                    !_pendingUserDeleteIds.contains(user.id) &&
                    !remoteIds.contains(user.id),
              )
              .toList();
          final mergedUsers = _mergeUserProfilesForCloud(
            pendingLocalUsers,
            remoteUsers,
          );

          if (remoteUsers.isNotEmpty ||
              pendingLocalUsers.isNotEmpty ||
              _usersCollectionHydrated) {
            setState(() {
              _users
                ..clear()
                ..addAll(mergedUsers);
              _currentUser =
                  _findUserById(_currentUser.id) ??
                  (_users.isNotEmpty ? _users.first : _currentUser);
              _ensureActiveTabAccess();
            });
            _persistState(pushCloud: false);
          }
        },
        onError: (_) {
          // Keep legacy snapshot sync as fallback if per-user listener fails.
        },
      );
    } catch (_) {
      // Keep legacy snapshot sync path available.
    }
  }

  void _startFieldRecordsRealtimeListeners() {
    _inseminationsRealtimeSubscription?.cancel();
    _inseminationsRealtimeSubscription = null;
    _healthRealtimeSubscription?.cancel();
    _healthRealtimeSubscription = null;
    if (!mounted || !_isCloudSyncAvailable() || !_isAuthenticated) {
      return;
    }

    try {
      _inseminationsRealtimeSubscription = _cloudInseminationsRef
          .orderBy('dose1DateMs', descending: true)
          .snapshots()
          .listen(
            (snapshot) {
              if (!mounted) {
                return;
              }
              final remoteRecords = snapshot.docs
                  .map((doc) {
                    final map = Map<String, dynamic>.from(doc.data());
                    if (_readString(map['id']).trim().isEmpty) {
                      map['id'] = doc.id;
                    }
                    return _inseminationFromJson(map);
                  })
                  .whereType<InseminationRecord>()
                  .toList();
              final remoteIds = remoteRecords
                  .map((record) => record.id.trim())
                  .where((id) => id.isNotEmpty)
                  .toSet();
              if (!_inseminationsCollectionHydrated) {
                _inseminationsCollectionHydrated = true;
                if (remoteRecords.isEmpty && _inseminations.isNotEmpty) {
                  for (final local in _inseminations) {
                    _pendingInseminationDeleteIds.remove(local.id);
                    _pendingInseminationUpsertIds.add(local.id);
                    unawaited(_upsertInseminationRecordToCloud(local));
                  }
                }
              }
              _pendingInseminationUpsertIds.removeWhere(remoteIds.contains);
              _pendingInseminationDeleteIds.removeWhere(
                (id) => !remoteIds.contains(id),
              );
              final pendingLocalRecords = _inseminations
                  .where(
                    (record) =>
                        _pendingInseminationUpsertIds.contains(record.id) &&
                        !_pendingInseminationDeleteIds.contains(record.id) &&
                        !remoteIds.contains(record.id),
                  )
                  .toList();
              final mergedRecords = _mergeInseminationRecordsForCloud(
                pendingLocalRecords,
                remoteRecords,
              );

              if (remoteRecords.isNotEmpty ||
                  pendingLocalRecords.isNotEmpty ||
                  _inseminationsCollectionHydrated) {
                setState(() {
                  _inseminations
                    ..clear()
                    ..addAll(mergedRecords);
                });
                _persistState(pushCloud: false);
              }
            },
            onError: (_) {
              // Keep snapshot sync as fallback if per-record listener fails.
            },
          );

      _healthRealtimeSubscription = _cloudHealthRecordsRef
          .orderBy('eventDateMs', descending: true)
          .snapshots()
          .listen(
            (snapshot) {
              if (!mounted) {
                return;
              }
              final remoteRecords = snapshot.docs
                  .map((doc) {
                    final map = Map<String, dynamic>.from(doc.data());
                    if (_readString(map['id']).trim().isEmpty) {
                      map['id'] = doc.id;
                    }
                    return _healthFromJson(map);
                  })
                  .whereType<HealthRecord>()
                  .toList();
              final remoteIds = remoteRecords
                  .map((record) => record.id.trim())
                  .where((id) => id.isNotEmpty)
                  .toSet();
              if (!_healthCollectionHydrated) {
                _healthCollectionHydrated = true;
                if (remoteRecords.isEmpty && _healthRecords.isNotEmpty) {
                  for (final local in _healthRecords) {
                    _pendingHealthDeleteIds.remove(local.id);
                    _pendingHealthUpsertIds.add(local.id);
                    unawaited(_upsertHealthRecordToCloud(local));
                  }
                }
              }
              _pendingHealthUpsertIds.removeWhere(remoteIds.contains);
              _pendingHealthDeleteIds.removeWhere(
                (id) => !remoteIds.contains(id),
              );
              final pendingLocalRecords = _healthRecords
                  .where(
                    (record) =>
                        _pendingHealthUpsertIds.contains(record.id) &&
                        !_pendingHealthDeleteIds.contains(record.id) &&
                        !remoteIds.contains(record.id),
                  )
                  .toList();
              final mergedRecords = _mergeHealthRecordsForCloud(
                pendingLocalRecords,
                remoteRecords,
              );

              if (remoteRecords.isNotEmpty ||
                  pendingLocalRecords.isNotEmpty ||
                  _healthCollectionHydrated) {
                setState(() {
                  _healthRecords
                    ..clear()
                    ..addAll(mergedRecords);
                });
                _persistState(pushCloud: false);
              }
            },
            onError: (_) {
              // Keep snapshot sync as fallback if per-record listener fails.
            },
          );
    } catch (_) {
      // Keep legacy sync path if per-record Firestore listeners are unavailable.
    }
  }

  void _scheduleCloudSyncPush() {
    if (!mounted ||
        !_cloudSyncActive ||
        !_isCloudSyncAvailable() ||
        _cloudApplyingSnapshot ||
        _stateLoading) {
      return;
    }
    _cloudSyncDebounceTimer?.cancel();
    _cloudSyncDebounceTimer = Timer(
      const Duration(milliseconds: _cloudSyncDebounceMilliseconds),
      () {
        _pushCloudSnapshotNow();
      },
    );
  }

  void _flushCloudSyncNow() {
    if (!mounted ||
        !_cloudSyncActive ||
        !_isCloudSyncAvailable() ||
        _cloudApplyingSnapshot ||
        _stateLoading) {
      return;
    }
    _cloudSyncDebounceTimer?.cancel();
    unawaited(_pushCloudSnapshotNow());
  }

  Future<bool> _pushCloudSnapshotNow() async {
    if (!mounted ||
        !_cloudSyncActive ||
        !_isCloudSyncAvailable() ||
        _cloudApplyingSnapshot ||
        _stateLoading) {
      return false;
    }

    final pushJobs = <Future<bool>>[];
    for (final documentId in _cloudSyncDocumentIds) {
      pushJobs.add(_pushCloudDocumentSnapshot(documentId));
    }
    try {
      final results = await Future.wait(pushJobs);
      final synced = results.isNotEmpty && results.every((result) => result);
      if (synced) {
        final now = DateTime.now();
        if (mounted) {
          setState(() {
            _lastCloudPersistedAt = now;
            _hasPendingCloudChanges = false;
          });
        } else {
          _lastCloudPersistedAt = now;
          _hasPendingCloudChanges = false;
        }
      }
      return synced;
    } catch (_) {
      // Defensive catch in case one of the jobs escapes local error handling.
      return false;
    }
  }

  Future<bool> _pushCloudDocumentSnapshot(String documentId) async {
    if (documentId == _cloudUsersSyncDocumentId &&
        _usesGranularUsersCloudSync()) {
      return true;
    }
    final version = _nextCloudVersionForDocument(documentId);
    final payload = await _buildMergedCloudPayloadForDocument(
      documentId,
      version,
    );
    try {
      await _cloudSyncDocRef(documentId).set(payload, SetOptions(merge: true));
      _markCloudVersionSeen(documentId, version);
      return true;
    } catch (_) {
      final fallbackPayload = _buildFallbackCloudPayloadForDocument(
        documentId,
        version,
      );
      if (fallbackPayload == null) {
        return false;
      }
      try {
        await _cloudSyncDocRef(
          documentId,
        ).set(fallbackPayload, SetOptions(merge: true));
        _markCloudVersionSeen(documentId, version);
        return true;
      } catch (_) {
        // Keep app usable offline or when backend is unavailable.
        return false;
      }
    }
  }

  Future<Map<String, dynamic>> _buildMergedCloudPayloadForDocument(
    String documentId,
    int version,
  ) async {
    if (documentId != _cloudChatSyncDocumentId &&
        documentId != _cloudNewsSyncDocumentId) {
      return _buildCloudPayloadForDocument(documentId, version);
    }

    try {
      final remoteSnapshot = await _cloudSyncDocRef(documentId).get();
      final remoteData = remoteSnapshot.data();
      if (remoteData == null || remoteData.isEmpty) {
        return _buildCloudPayloadForDocument(documentId, version);
      }

      if (documentId == _cloudChatSyncDocumentId) {
        final remoteMessages = _readCloudModelList(
          remoteData['chatMessages'],
          _chatMessageFromJson,
        );
        final mergedMessages = _mergeChatMessagesForSync(
          _chatMessages,
          remoteMessages,
        );
        return _cloudPayloadEnvelope(
          version: version,
          data: {
            'chatMessages': _buildCloudChatPayload(
              sourceMessages: mergedMessages,
            ),
          },
        );
      }

      final remotePosts = _readCloudModelList(
        remoteData['newsPosts'],
        _newsPostFromJson,
      );
      final mergedPosts = _mergeNewsPostsForSync(_newsPosts, remotePosts);
      return _cloudPayloadEnvelope(
        version: version,
        data: {'newsPosts': _buildCloudNewsPayload(sourcePosts: mergedPosts)},
      );
    } catch (_) {
      return _buildCloudPayloadForDocument(documentId, version);
    }
  }

  Map<String, dynamic>? _buildFallbackCloudPayloadForDocument(
    String documentId,
    int version,
  ) {
    switch (documentId) {
      case _cloudChatSyncDocumentId:
        return _cloudPayloadEnvelope(
          version: version,
          data: {
            'chatMessages': _buildCloudChatPayload(
              maxMessages: _cloudChatFallbackSyncLimit,
              budgetBytes: _cloudChatPayloadBudgetBytes ~/ 2,
              includeMedia: false,
            ),
          },
        );
      case _cloudNewsSyncDocumentId:
        return _cloudPayloadEnvelope(
          version: version,
          data: {
            'newsPosts': _buildCloudNewsPayload(
              maxPosts: _cloudNewsFallbackSyncLimit,
              budgetBytes: _cloudNewsPayloadBudgetBytes ~/ 2,
              includeImages: false,
            ),
          },
        );
      default:
        return null;
    }
  }

  void _applyCloudSnapshot(String documentId, Map<String, dynamic>? data) {
    if (!mounted || data == null || data.isEmpty) {
      return;
    }

    final remoteVersion = _readCloudVersion(data);
    if (remoteVersion <= _cloudVersionSeenForDocument(documentId)) {
      return;
    }

    _cloudApplyingSnapshot = true;
    setState(() {
      switch (documentId) {
        case _cloudUsersSyncDocumentId:
          if (_usesGranularUsersCloudSync() && _users.isNotEmpty) {
            break;
          }
          if (data.containsKey('users')) {
            final remoteUsers = _readCloudModelList(
              data['users'],
              _userFromJson,
            );
            final effectiveUsers = _mergeWithRequiredSystemUsers(
              remoteUsers.isNotEmpty ? remoteUsers : initialUsers,
            );
            _users
              ..clear()
              ..addAll(effectiveUsers);
            _currentUser =
                _findUserById(_currentUser.id) ??
                (_users.isNotEmpty ? _users.first : _currentUser);
          }
          break;
        case _cloudLivestockSyncDocumentId:
          if (data.containsKey('boars')) {
            _boars
              ..clear()
              ..addAll(_readCloudModelList(data['boars'], _boarFromJson));
          }
          if (data.containsKey('sows')) {
            _sows
              ..clear()
              ..addAll(_readCloudModelList(data['sows'], _sowFromJson));
          }
          if (data.containsKey('inseminations')) {
            _inseminations
              ..clear()
              ..addAll(
                _readCloudModelList(
                  data['inseminations'],
                  _inseminationFromJson,
                ),
              );
          }
          if (data.containsKey('healthRecords')) {
            _healthRecords
              ..clear()
              ..addAll(
                _readCloudModelList(data['healthRecords'], _healthFromJson),
              );
          }
          if (data.containsKey('semenQualityRecords')) {
            _semenQualityRecords
              ..clear()
              ..addAll(
                _readCloudModelList(
                  data['semenQualityRecords'],
                  _semenQualityFromJson,
                ),
              );
          }
          break;
        case _cloudCommercialSyncDocumentId:
          if (data.containsKey('clients')) {
            _clients
              ..clear()
              ..addAll(_readCloudModelList(data['clients'], _clientFromJson));
          }
          if (data.containsKey('suppliers')) {
            _suppliers
              ..clear()
              ..addAll(
                _readCloudModelList(data['suppliers'], _supplierFromJson),
              );
          }
          if (data.containsKey('salesRecords')) {
            _salesRecords
              ..clear()
              ..addAll(
                _readCloudModelList(data['salesRecords'], _saleFromJson),
              );
          }
          if (data.containsKey('animalSaleListings')) {
            _animalSaleListings
              ..clear()
              ..addAll(
                _readCloudModelList(
                  data['animalSaleListings'],
                  _animalSaleListingFromJson,
                ),
              );
          }
          if (data.containsKey('supplyRecords')) {
            _supplyRecords
              ..clear()
              ..addAll(
                _readCloudModelList(data['supplyRecords'], _supplyFromJson),
              );
          }
          break;
        case _cloudOperationsSyncDocumentId:
          if (data.containsKey('buildings')) {
            _buildings
              ..clear()
              ..addAll(
                _readCloudModelList(data['buildings'], _buildingFromJson),
              );
          }
          if (data.containsKey('batchRecords')) {
            _batchRecords
              ..clear()
              ..addAll(
                _readCloudModelList(data['batchRecords'], _batchFromJson),
              );
          }
          if (data.containsKey('growthRecords')) {
            _growthRecords
              ..clear()
              ..addAll(
                _readCloudModelList(data['growthRecords'], _growthFromJson),
              );
          }
          if (data.containsKey('pigletCareRecords')) {
            _pigletCareRecords
              ..clear()
              ..addAll(
                _readCloudModelList(
                  data['pigletCareRecords'],
                  _pigletCareFromJson,
                ),
              );
          }
          if (data.containsKey('farrowingRecords')) {
            _farrowingRecords
              ..clear()
              ..addAll(
                _readCloudModelList(
                  data['farrowingRecords'],
                  _farrowingFromJson,
                ),
              );
          }
          if (data.containsKey('auditLogs')) {
            final auditLogs = _readCloudModelList(
              data['auditLogs'],
              _auditLogFromJson,
            )..sort((a, b) => b.timestamp.compareTo(a.timestamp));
            _auditLogs
              ..clear()
              ..addAll(auditLogs);
          }
          if (data.containsKey('taskDoneById')) {
            _taskDoneById
              ..clear()
              ..addAll(
                _readObjectMap(data['taskDoneById']).map(
                  (key, value) =>
                      MapEntry(key, value.toString().toLowerCase() == 'true'),
                ),
              );
          }
          break;
        case _cloudChatSyncDocumentId:
          if (data.containsKey('chatMessages')) {
            final incomingChat = _readCloudModelList(
              data['chatMessages'],
              _chatMessageFromJson,
            );
            _mergeChatMessagesInState(incomingChat);
          }
          break;
        case _cloudNewsSyncDocumentId:
          if (data.containsKey('newsPosts')) {
            final incomingNews = _readCloudModelList(
              data['newsPosts'],
              _newsPostFromJson,
            );
            _mergeNewsPostsInState(incomingNews);
          }
          break;
      }
      _preferredBoarCode = _resolvePreferredBoarCode(_preferredBoarCode);
      _selectedPedigreeAnimalCode = _resolveSelectedPedigreeCode(
        _selectedPedigreeAnimalCode,
        _allPedigreeNodes(),
      );
      if (!_canAccessTab(_activeTab)) {
        _activeTab = _defaultTabForCurrentUser();
      }
    });
    _cloudApplyingSnapshot = false;
    _markCloudVersionSeen(documentId, remoteVersion);
    _syncIncomingCallOffer();
    _persistState(pushCloud: false);
  }

  Map<String, dynamic> _readObjectMap(dynamic value) {
    if (value is! Map) {
      return const {};
    }
    return Map<String, dynamic>.from(value);
  }

  List<Map<String, dynamic>> _readObjectMapList(dynamic value) {
    if (value is! List) {
      return const [];
    }
    final items = <Map<String, dynamic>>[];
    for (final item in value) {
      if (item is Map) {
        items.add(Map<String, dynamic>.from(item));
      }
    }
    return items;
  }

  List<T> _readCloudModelList<T>(
    dynamic value,
    T? Function(Map<String, dynamic>) fromJson,
  ) {
    return _readObjectMapList(value).map(fromJson).whereType<T>().toList();
  }

  List<Map<String, dynamic>> _buildCloudObjectList<T>(
    List<T> items,
    Map<String, dynamic> Function(T item) toJson,
  ) {
    return items.map(toJson).toList();
  }

  Map<String, dynamic> _trimCloudBase64Fields(
    Map<String, dynamic> json,
    Iterable<String> fields,
  ) {
    final sanitized = Map<String, dynamic>.from(json);
    for (final field in fields) {
      sanitized[field] = _cloudTrimBase64(_readString(sanitized[field]));
    }
    return sanitized;
  }

  Map<String, dynamic> _userToCloudJson(UserProfile user) {
    return _trimCloudBase64Fields(_userToJson(user), [
      'profileImageBase64',
      'coverImageBase64',
    ]);
  }

  Map<String, dynamic> _boarToCloudJson(Boar boar) {
    return _trimCloudBase64Fields(_boarToJson(boar), ['imageBase64']);
  }

  Map<String, dynamic> _sowToCloudJson(Sow sow) {
    return _trimCloudBase64Fields(_sowToJson(sow), ['imageBase64']);
  }

  Map<String, dynamic> _animalSaleListingToCloudJson(
    AnimalSaleListing listing,
  ) {
    return _trimCloudBase64Fields(_animalSaleListingToJson(listing), [
      'imageBase64',
    ]);
  }

  List<Map<String, dynamic>> _buildCloudChatPayload({
    List<ChatMessage>? sourceMessages,
    int maxMessages = _cloudChatSyncLimit,
    int budgetBytes = _cloudChatPayloadBudgetBytes,
    bool includeMedia = true,
  }) {
    final sorted = List<ChatMessage>.from(sourceMessages ?? _chatMessages)
      ..sort((a, b) => a.sentAt.compareTo(b.sentAt));
    final fromIndex = math.max(0, sorted.length - maxMessages);
    final limited = sorted.sublist(fromIndex);

    final payload = <Map<String, dynamic>>[];
    var payloadBytes = 2;
    for (var index = limited.length - 1; index >= 0; index--) {
      final message = limited[index];
      var candidate = _chatMessageToCloudJson(
        message,
        includeMedia: includeMedia,
      );
      var candidateBytes = _estimateJsonBytes(candidate) + 1;
      if (payloadBytes + candidateBytes > budgetBytes && includeMedia) {
        candidate = _chatMessageToCloudJson(message, includeMedia: false);
        candidateBytes = _estimateJsonBytes(candidate) + 1;
      }
      if (payloadBytes + candidateBytes > budgetBytes) {
        if (payload.isEmpty) {
          payload.add(_chatMessageToCloudJson(message, includeMedia: false));
        }
        break;
      }
      payload.insert(0, candidate);
      payloadBytes += candidateBytes;
    }

    return payload;
  }

  List<ChatMessage> _mergeChatMessagesForSync(
    List<ChatMessage> localMessages,
    List<ChatMessage> remoteMessages,
  ) {
    final byId = <String, ChatMessage>{};
    for (final message in remoteMessages) {
      byId[message.id] = message;
    }
    for (final message in localMessages) {
      final existing = byId[message.id];
      if (existing == null) {
        byId[message.id] = message;
      } else {
        byId[message.id] = _mergeChatMessage(existing, message);
      }
    }
    final merged = byId.values.toList()
      ..sort((a, b) => a.sentAt.compareTo(b.sentAt));
    if (merged.length > 2500) {
      merged.removeRange(0, merged.length - 2500);
    }
    return merged;
  }

  List<UserProfile> _mergeUserProfilesForCloud(
    List<UserProfile> localUsers,
    List<UserProfile> remoteUsers,
  ) {
    final byId = <String, UserProfile>{};
    for (final user in remoteUsers) {
      final id = user.id.trim();
      if (id.isEmpty) {
        continue;
      }
      byId[id] = user;
    }
    for (final user in localUsers) {
      final id = user.id.trim();
      if (id.isEmpty) {
        continue;
      }
      byId[id] = user;
    }
    final merged = _mergeWithRequiredSystemUsers(byId.values).toList()
      ..sort(
        (a, b) =>
            a.name.trim().toLowerCase().compareTo(b.name.trim().toLowerCase()),
      );
    return merged;
  }

  void _mergeChatMessagesInState(List<ChatMessage> incomingMessages) {
    if (incomingMessages.isEmpty) {
      return;
    }
    final byId = <String, ChatMessage>{};
    for (final message in _chatMessages) {
      byId[message.id] = message;
    }
    for (final incoming in incomingMessages) {
      final existing = byId[incoming.id];
      if (existing == null) {
        byId[incoming.id] = incoming;
        continue;
      }
      byId[incoming.id] = _mergeChatMessage(existing, incoming);
    }
    final merged = byId.values.toList()
      ..sort((a, b) => a.sentAt.compareTo(b.sentAt));
    if (merged.length > 2500) {
      merged.removeRange(0, merged.length - 2500);
    }
    _chatMessages
      ..clear()
      ..addAll(merged);
  }

  ChatMessage _mergeChatMessage(ChatMessage current, ChatMessage incoming) {
    final mergedReadBy = <String>{
      ...current.readByUserIds,
      ...incoming.readByUserIds,
    }.toList();
    mergedReadBy.sort();

    return ChatMessage(
      id: current.id,
      conversationId: incoming.conversationId.trim().isEmpty
          ? current.conversationId
          : incoming.conversationId,
      senderId: incoming.senderId.trim().isEmpty
          ? current.senderId
          : incoming.senderId,
      senderName: incoming.senderName.trim().isEmpty
          ? current.senderName
          : incoming.senderName,
      text: incoming.text.trim().isNotEmpty ? incoming.text : current.text,
      sentAt: incoming.sentAt.isAfter(current.sentAt)
          ? incoming.sentAt
          : current.sentAt,
      readByUserIds: mergedReadBy,
      messageType: incoming.messageType.trim().isEmpty
          ? current.messageType
          : incoming.messageType,
      mediaBase64: incoming.mediaBase64.trim().isNotEmpty
          ? incoming.mediaBase64
          : current.mediaBase64,
      mediaName: incoming.mediaName.trim().isNotEmpty
          ? incoming.mediaName
          : current.mediaName,
      mediaMimeType: incoming.mediaMimeType.trim().isNotEmpty
          ? incoming.mediaMimeType
          : current.mediaMimeType,
      mediaSizeBytes: incoming.mediaSizeBytes > 0
          ? incoming.mediaSizeBytes
          : current.mediaSizeBytes,
      callType: incoming.callType.trim().isNotEmpty
          ? incoming.callType
          : current.callType,
      callStatus: incoming.callStatus.trim().isNotEmpty
          ? incoming.callStatus
          : current.callStatus,
      callDurationSeconds: math.max(
        current.callDurationSeconds,
        incoming.callDurationSeconds,
      ),
      callSessionId: incoming.callSessionId.trim().isNotEmpty
          ? incoming.callSessionId
          : current.callSessionId,
    );
  }

  void _mergeNewsPostsInState(List<NewsPost> incomingPosts) {
    if (incomingPosts.isEmpty) {
      return;
    }

    final mergedById = <String, NewsPost>{};
    final incomingById = <String, NewsPost>{};
    for (final post in incomingPosts) {
      incomingById[post.id] = post;
      mergedById[post.id] = post;
    }

    final incomingLikelyTrimmed = incomingPosts.length >= _cloudNewsSyncLimit;
    for (final local in _newsPosts) {
      final incoming = incomingById[local.id];
      if (incoming != null) {
        mergedById[local.id] = _mergeNewsPost(local, incoming);
      } else if (incomingLikelyTrimmed) {
        mergedById[local.id] = local;
      }
    }

    final merged = mergedById.values.toList()
      ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
    if (merged.length > 400) {
      merged.removeRange(400, merged.length);
    }
    _newsPosts
      ..clear()
      ..addAll(merged);
  }

  NewsPost _mergeNewsPost(NewsPost current, NewsPost incoming) {
    final mergedLikes = <String>{
      ...current.likedByUserIds,
      ...incoming.likedByUserIds,
    }.toList()..sort();

    final commentsById = <String, NewsComment>{};
    for (final comment in current.comments) {
      commentsById[comment.id] = comment;
    }
    for (final comment in incoming.comments) {
      final existing = commentsById[comment.id];
      if (existing == null || comment.createdAt.isAfter(existing.createdAt)) {
        commentsById[comment.id] = comment;
      }
    }
    final mergedComments = commentsById.values.toList()
      ..sort((a, b) => a.createdAt.compareTo(b.createdAt));

    final incomingHasImage =
        incoming.imageBase64.trim().isNotEmpty ||
        incoming.imageName.trim().isNotEmpty;
    final mergedCreatedAt = incoming.createdAt.isBefore(current.createdAt)
        ? incoming.createdAt
        : current.createdAt;

    return NewsPost(
      id: current.id,
      authorId: incoming.authorId.trim().isNotEmpty
          ? incoming.authorId
          : current.authorId,
      authorName: incoming.authorName.trim().isNotEmpty
          ? incoming.authorName
          : current.authorName,
      authorRole: incoming.authorRole.trim().isNotEmpty
          ? incoming.authorRole
          : current.authorRole,
      text:
          incoming.text.trim().isEmpty &&
              current.text.trim().isNotEmpty &&
              !incomingHasImage
          ? current.text
          : incoming.text,
      createdAt: mergedCreatedAt,
      imageBase64: incomingHasImage
          ? incoming.imageBase64
          : current.imageBase64,
      imageName: incomingHasImage ? incoming.imageName : current.imageName,
      likedByUserIds: mergedLikes,
      comments: mergedComments,
    );
  }

  Map<String, dynamic> _chatMessageToCloudJson(
    ChatMessage message, {
    bool includeMedia = true,
  }) {
    return {
      'id': message.id,
      'conversationId': message.conversationId,
      'senderId': message.senderId,
      'senderName': message.senderName,
      'text': message.text,
      'sentAt': message.sentAt.toUtc().toIso8601String(),
      'readByUserIds': message.readByUserIds,
      'messageType': message.messageType,
      'mediaBase64': includeMedia ? _cloudTrimBase64(message.mediaBase64) : '',
      'mediaName': includeMedia ? message.mediaName : '',
      'mediaMimeType': includeMedia ? message.mediaMimeType : '',
      'mediaSizeBytes': includeMedia ? message.mediaSizeBytes : 0,
      'callType': message.callType,
      'callStatus': message.callStatus,
      'callDurationSeconds': message.callDurationSeconds,
      'callSessionId': message.callSessionId,
    };
  }

  List<Map<String, dynamic>> _buildCloudNewsPayload({
    List<NewsPost>? sourcePosts,
    int maxPosts = _cloudNewsSyncLimit,
    int budgetBytes = _cloudNewsPayloadBudgetBytes,
    bool includeImages = true,
  }) {
    final sorted = List<NewsPost>.from(sourcePosts ?? _newsPosts)
      ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
    final limited = sorted.take(maxPosts).toList();

    final payload = <Map<String, dynamic>>[];
    var payloadBytes = 2;
    for (final post in limited) {
      var candidate = _newsPostToCloudJson(post, includeImage: includeImages);
      var candidateBytes = _estimateJsonBytes(candidate) + 1;
      if (payloadBytes + candidateBytes > budgetBytes && includeImages) {
        candidate = _newsPostToCloudJson(post, includeImage: false);
        candidateBytes = _estimateJsonBytes(candidate) + 1;
      }
      if (payloadBytes + candidateBytes > budgetBytes) {
        break;
      }
      payload.add(candidate);
      payloadBytes += candidateBytes;
    }

    return payload;
  }

  List<NewsPost> _mergeNewsPostsForSync(
    List<NewsPost> localPosts,
    List<NewsPost> remotePosts,
  ) {
    final byId = <String, NewsPost>{};
    for (final post in remotePosts) {
      byId[post.id] = post;
    }
    for (final post in localPosts) {
      final existing = byId[post.id];
      if (existing == null) {
        byId[post.id] = post;
      } else {
        byId[post.id] = _mergeNewsPost(existing, post);
      }
    }
    final merged = byId.values.toList()
      ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
    if (merged.length > 400) {
      merged.removeRange(400, merged.length);
    }
    return merged;
  }

  List<InseminationRecord> _mergeInseminationRecordsForCloud(
    List<InseminationRecord> localRecords,
    List<InseminationRecord> remoteRecords,
  ) {
    final byId = <String, InseminationRecord>{};
    for (final record in remoteRecords) {
      byId[record.id] = record;
    }
    for (final record in localRecords) {
      byId.putIfAbsent(record.id, () => record);
    }
    final merged = byId.values.toList()
      ..sort((a, b) => b.dose1Date.compareTo(a.dose1Date));
    return merged;
  }

  List<HealthRecord> _mergeHealthRecordsForCloud(
    List<HealthRecord> localRecords,
    List<HealthRecord> remoteRecords,
  ) {
    final byId = <String, HealthRecord>{};
    for (final record in remoteRecords) {
      byId[record.id] = record;
    }
    for (final record in localRecords) {
      byId.putIfAbsent(record.id, () => record);
    }
    final merged = byId.values.toList()
      ..sort((a, b) => b.eventDate.compareTo(a.eventDate));
    return merged;
  }

  Map<String, dynamic> _newsPostToCloudJson(
    NewsPost post, {
    bool includeImage = true,
  }) {
    return {
      'id': post.id,
      'authorId': post.authorId,
      'authorName': post.authorName,
      'authorRole': post.authorRole,
      'text': post.text,
      'createdAt': post.createdAt.toUtc().toIso8601String(),
      'imageBase64': includeImage ? _cloudTrimBase64(post.imageBase64) : '',
      'imageName': includeImage ? post.imageName : '',
      'likedByUserIds': post.likedByUserIds,
      'comments': post.comments
          .take(includeImage ? 40 : 20)
          .map(_newsCommentToJson)
          .toList(),
    };
  }

  String _cloudTrimBase64(String raw) {
    final value = raw.trim();
    if (value.length > _cloudInlineMediaBase64MaxLength) {
      return '';
    }
    return value;
  }

  int _estimateJsonBytes(dynamic value) {
    try {
      return utf8.encode(jsonEncode(value)).length;
    } catch (_) {
      return 0;
    }
  }

  List<Map<String, dynamic>>? _decodeObjectListOrNull(String? raw) {
    if (raw == null) {
      return null;
    }
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! List) {
        return null;
      }
      final items = <Map<String, dynamic>>[];
      for (final item in decoded) {
        if (item is Map) {
          items.add(Map<String, dynamic>.from(item));
        }
      }
      return items;
    } catch (_) {
      return null;
    }
  }

  Map<String, dynamic>? _decodeObjectMapOrNull(String? raw) {
    if (raw == null) {
      return null;
    }
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! Map) {
        return null;
      }
      return Map<String, dynamic>.from(decoded);
    } catch (_) {
      return null;
    }
  }

  String _readString(dynamic value) {
    if (value == null) {
      return '';
    }
    return value.toString();
  }

  int _readInt(dynamic value) {
    if (value is int) {
      return value;
    }
    return int.tryParse(_readString(value)) ?? 0;
  }

  double _readDouble(dynamic value) {
    if (value is num) {
      return value.toDouble();
    }
    return double.tryParse(_readString(value)) ?? 0;
  }

  List<String> _readStringList(dynamic value) {
    if (value is! List) {
      return const [];
    }
    final items = <String>[];
    for (final item in value) {
      final text = _readString(item).trim();
      if (text.isEmpty || items.contains(text)) {
        continue;
      }
      items.add(text);
    }
    return items;
  }

  DateTime? _parseDateFromString(String? raw) {
    if (raw == null || raw.trim().isEmpty) {
      return null;
    }
    final parsed = DateTime.tryParse(raw.trim());
    if (parsed == null) {
      return null;
    }
    return DateTime(parsed.year, parsed.month, parsed.day);
  }

  DateTime? _parseDateTimeFromString(String? raw) {
    if (raw == null || raw.trim().isEmpty) {
      return null;
    }
    final parsed = DateTime.tryParse(raw.trim());
    if (parsed == null) {
      return null;
    }
    return parsed.toLocal();
  }

  String? _resolvePreferredBoarCode(String? rawCode) {
    if (_boars.isEmpty) {
      return null;
    }
    final normalized = _readString(rawCode).trim().toLowerCase();
    if (normalized.isEmpty) {
      return _boars.first.code;
    }
    for (final boar in _boars) {
      if (boar.code.trim().toLowerCase() == normalized) {
        return boar.code;
      }
    }
    return _boars.first.code;
  }

  List<_PedigreeTreeNode> _allPedigreeNodes() {
    final nodesByCode = <String, _PedigreeTreeNode>{};

    for (final boar in _boars) {
      final node = _PedigreeTreeNode(
        code: boar.code,
        name: boar.name,
        type: 'Verrat',
        breed: boar.breed,
        birthDate: boar.birthDate,
        breederId: boar.breederId,
        sireCode: boar.sireCode,
        damCode: boar.damCode,
        origin: boar.origin,
      );
      nodesByCode[_normalizeLookup(boar.code)] = node;
    }

    for (final sow in _sows) {
      final key = _normalizeLookup(sow.code);
      if (nodesByCode.containsKey(key)) {
        continue;
      }
      nodesByCode[key] = _PedigreeTreeNode(
        code: sow.code,
        name: sow.name,
        type: 'Truie',
        breed: sow.breed,
        birthDate: sow.birthDate,
        breederId: sow.breederId,
        sireCode: sow.sireCode,
        damCode: sow.damCode,
        origin: '',
      );
    }

    final nodes = nodesByCode.values.toList()
      ..sort((a, b) {
        if (a.type != b.type) {
          return a.type == 'Verrat' ? -1 : 1;
        }
        return a.code.compareTo(b.code);
      });
    return nodes;
  }

  String? _resolveSelectedPedigreeCode(
    String? rawCode,
    List<_PedigreeTreeNode> nodes,
  ) {
    if (nodes.isEmpty) {
      return null;
    }
    final normalized = _normalizeLookup(_readString(rawCode));
    if (normalized.isEmpty) {
      return nodes.first.code;
    }
    for (final node in nodes) {
      if (_normalizeLookup(node.code) == normalized) {
        return node.code;
      }
    }
    return nodes.first.code;
  }

  List<UserProfile> _mergeWithRequiredSystemUsers(Iterable<UserProfile> users) {
    final merged = List<UserProfile>.from(users);

    bool alreadyExists(UserProfile candidate) {
      final id = candidate.id.trim().toLowerCase();
      final code = candidate.code.trim().toLowerCase();
      final login = candidate.login.trim().toLowerCase();
      for (final user in merged) {
        if (user.id.trim().toLowerCase() == id ||
            user.code.trim().toLowerCase() == code ||
            user.login.trim().toLowerCase() == login) {
          return true;
        }
      }
      return false;
    }

    for (final seed in initialUsers) {
      if (alreadyExists(seed)) {
        continue;
      }
      merged.add(
        UserProfile(
          id: seed.id,
          code: seed.code,
          name: seed.name,
          role: seed.role,
          avatar: seed.avatar,
          address: seed.address,
          contact: seed.contact,
          fokontany: seed.fokontany,
          commune: seed.commune,
          district: seed.district,
          region: seed.region,
          bio: seed.bio,
          profileImageBase64: seed.profileImageBase64,
          coverImageBase64: seed.coverImageBase64,
          login: seed.login,
          password: _isHashedPassword(seed.password)
              ? seed.password
              : _hashPassword(seed.password),
        ),
      );
    }
    return merged;
  }

