  Widget _buildBrandLogo({required double height, BorderRadius? borderRadius}) {
    final image = Image.asset(
      _brandLogoAsset,
      height: height,
      fit: BoxFit.contain,
      filterQuality: FilterQuality.high,
      errorBuilder: (context, error, stackTrace) {
        return Container(
          height: height * 0.56,
          padding: const EdgeInsets.symmetric(
            horizontal: AppSpacing.lg,
            vertical: AppSpacing.xs,
          ),
          decoration: BoxDecoration(
            color: _accentTeal.withValues(alpha: 0.15),
            borderRadius: BorderRadius.circular(AppSpacing.lg),
            border: Border.all(color: _accentTeal.withValues(alpha: 0.5)),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: const [
              Icon(
                LucideIcons.piggyBank,
                color: AppColors.primaryDark,
                size: AppSpacing.xxl,
              ),
              SizedBox(width: AppSpacing.xs),
              Text(
                'PIGIA',
                style: TextStyle(
                  color: AppColors.textPrimary,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 0.1,
                ),
              ),
            ],
          ),
        );
      },
    );
    if (borderRadius == null) {
      return image;
    }
    return ClipRRect(borderRadius: borderRadius, child: image);
  }

  Widget _buildNavItem({
    required IconData icon,
    required String label,
    required String tabId,
  }) {
    final isActive = _activeTab == tabId;

    return Padding(
      padding: const EdgeInsets.only(bottom: AppSpacing.s4),
      child: InkWell(
        borderRadius: BorderRadius.circular(12),
        onTap: () {
          if (!_canAccessTab(tabId)) {
            _showError('Accès refusé pour le rôle ${_currentUser.role}.');
            return;
          }
          setState(() {
            _activeTab = tabId;
            if (tabId != AppTabs.messenger) {
              _isMobileMessengerThreadOpen = false;
            }
          });
          _persistState();
          if (_scaffoldKey.currentState?.isDrawerOpen ?? false) {
            Navigator.of(context).pop();
          }
        },
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 200),
          curve: Curves.easeOutCubic,
          padding: const EdgeInsets.symmetric(
            horizontal: AppSpacing.s12,
            vertical: AppSpacing.s10,
          ),
          decoration: BoxDecoration(
            color: isActive
                ? AppColors.sidebarActiveBg.withValues(alpha: 0.24)
                : Colors.transparent,
            borderRadius: BorderRadius.circular(12),
            border: isActive
                ? Border.all(
                    color: AppColors.sidebarActiveBg.withValues(alpha: 0.56),
                  )
                : Border.all(color: Colors.transparent),
          ),
          child: Row(
            children: [
              Container(
                width: 32,
                height: 32,
                decoration: BoxDecoration(
                  color: isActive
                      ? AppColors.sidebarActiveBg.withValues(alpha: 0.26)
                      : Colors.white.withValues(alpha: 0.72),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Icon(
                  icon,
                  color: isActive
                      ? AppColors.primaryDark
                      : AppColors.sidebarText,
                  size: 16,
                ),
              ),
              const SizedBox(width: AppSpacing.s10),
              Expanded(
                child: Text(
                  label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    color: isActive
                        ? AppColors.sidebarTextActive
                        : AppColors.sidebarText,
                    fontWeight: isActive ? FontWeight.w700 : FontWeight.w600,
                    fontSize: 13,
                  ),
                ),
              ),
              if (isActive)
                Container(
                  width: 4,
                  height: 18,
                  decoration: BoxDecoration(
                    color: AppColors.primaryDark,
                    borderRadius: BorderRadius.circular(2),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }

