  Widget _buildHeader(bool isDesktop) {
    final screenWidth = MediaQuery.of(context).size.width;
    final compact = screenWidth < 680;
    final tiny = screenWidth < 430;
    final showDate = !_isBreederSimpleUi && screenWidth >= 700;
    final showSearch = !_isBreederSimpleUi && screenWidth >= 1180;
    final showLoginBadge = !_isBreederSimpleUi && screenWidth >= 980;
    final notificationCount = _headerNotificationCount();

    if (_activeTab == AppTabs.actualites) {
      return Container(
        height: 68,
        padding: const EdgeInsets.symmetric(horizontal: AppSpacing.s10),
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.centerLeft,
            end: Alignment.centerRight,
            colors: [AppColors.newsHeaderStart, AppColors.newsHeaderEnd],
          ),
          border: Border(bottom: BorderSide(color: AppColors.border)),
        ),
        child: Row(
          children: [
            if (!isDesktop)
              IconButton(
                tooltip: 'Menu',
                onPressed: () => _scaffoldKey.currentState?.openDrawer(),
                icon: const Icon(
                  LucideIcons.menu,
                  color: AppColors.textPrimary,
                ),
              ),
            Expanded(
              child: Text(
                _uiLabel(fr: 'Actualités', mg: 'Vaovao'),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: AppColors.textPrimary,
                  fontWeight: FontWeight.w900,
                  fontSize: 20,
                  letterSpacing: -0.4,
                ),
              ),
            ),
            Container(
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: 0.55),
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: AppColors.borderLight),
              ),
              child: IconButton(
                tooltip: _uiLabel(
                  fr: 'Créer une publication',
                  mg: 'Hamorona famoahana',
                ),
                onPressed: _showAddNewsPostDialog,
                icon: const Icon(
                  Icons.add_circle_outline,
                  color: AppColors.textPrimary,
                ),
              ),
            ),
            const SizedBox(width: AppSpacing.s4),
            _buildHeaderNotificationButton(notificationCount),
          ],
        ),
      );
    }

    return Container(
      height: tiny ? 68 : 78,
      padding: EdgeInsets.symmetric(
        horizontal: tiny
            ? AppSpacing.s6
            : (compact ? AppSpacing.s10 : AppSpacing.s18),
      ),
      decoration: const BoxDecoration(
        color: AppColors.headerBg,
        border: Border(bottom: BorderSide(color: AppColors.headerBorder)),
      ),
      child: Row(
        children: [
          Expanded(
            child: Row(
              children: [
                if (!isDesktop)
                  IconButton(
                    icon: const Icon(LucideIcons.menu),
                    onPressed: () => _scaffoldKey.currentState?.openDrawer(),
                  ),
                if (!showSearch)
                  IconButton(
                    tooltip: _uiLabel(fr: 'Recherche', mg: 'Fikarohana'),
                    onPressed: _openSearchDialog,
                    icon: const Icon(
                      Icons.search,
                      color: AppColors.textSecondary,
                    ),
                  ),
                Expanded(
                  child: showSearch
                      ? _buildHeaderSearchField()
                      : Text(
                          compact
                              ? _compactTitleForTab(_activeTab)
                              : _titleForTab(_activeTab),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: GoogleFonts.inter(
                            fontSize: tiny ? 11 : (compact ? 13 : 17),
                            fontWeight: FontWeight.w900,
                            letterSpacing: -0.5,
                            color: AppColors.textPrimary,
                          ),
                        ),
                ),
              ],
            ),
          ),
          const SizedBox(width: AppSpacing.s8),
          _buildHeaderNotificationButton(notificationCount),
          if (showDate) ...[
            const SizedBox(width: AppSpacing.s10),
            Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Text(
                  _uiLabel(fr: 'AUJOURD\'HUI', mg: 'ANDROANY'),
                  style: const TextStyle(
                    fontSize: 9,
                    fontWeight: FontWeight.bold,
                    color: AppColors.textMuted,
                  ),
                ),
                Text(
                  DateFormat(
                    compact ? 'd MMM' : 'EEEE d MMMM',
                    'fr_FR',
                  ).format(DateTime.now()),
                  style: const TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w800,
                    color: AppColors.textSecondary,
                  ),
                ),
              ],
            ),
          ],
          const SizedBox(width: AppSpacing.s8),
          if (showLoginBadge)
            Container(
              padding: const EdgeInsets.symmetric(
                horizontal: AppSpacing.s10,
                vertical: AppSpacing.s7,
              ),
              decoration: BoxDecoration(
                color: _surfaceSlate,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: AppColors.borderLight),
              ),
              child: Row(
                children: [
                  _buildUserAvatar(_currentUser, radius: 12),
                  const SizedBox(width: AppSpacing.s8),
                  Text(
                    '${_uiLabel(fr: 'Login', mg: 'Anarana fidirana')}: ${_currentUser.login}',
                    style: const TextStyle(
                      color: AppColors.textPrimary,
                      fontWeight: FontWeight.w700,
                      fontSize: 12,
                    ),
                  ),
                ],
              ),
            ),
          if (showLoginBadge) const SizedBox(width: AppSpacing.s8),
          if (showLoginBadge)
            OutlinedButton.icon(
              style: OutlinedButton.styleFrom(
                foregroundColor: _accentTealDeep,
                side: BorderSide(color: _accentTeal.withValues(alpha: 0.4)),
                padding: const EdgeInsets.symmetric(
                  horizontal: AppSpacing.s12,
                  vertical: AppSpacing.s10,
                ),
              ),
              onPressed: () {
                setState(() => _activeTab = AppTabs.profile);
                _persistState();
              },
              icon: const Icon(Icons.account_circle_outlined, size: 16),
              label: Text(_uiLabel(fr: 'Profil', mg: 'Mombamomba')),
            ),
          if (showLoginBadge) const SizedBox(width: AppSpacing.s8),
          if (showLoginBadge)
            OutlinedButton.icon(
              style: OutlinedButton.styleFrom(
                foregroundColor: AppColors.textSecondary,
                side: const BorderSide(color: AppColors.border),
                padding: const EdgeInsets.symmetric(
                  horizontal: AppSpacing.s12,
                  vertical: AppSpacing.s10,
                ),
              ),
              onPressed: _logout,
              icon: const Icon(Icons.logout, size: 16),
              label: Text(_uiLabel(fr: 'Déconnexion', mg: 'Hivoaka')),
            )
          else
            IconButton(
              tooltip: _uiLabel(fr: 'Déconnexion', mg: 'Hivoaka'),
              onPressed: _logout,
              icon: const Icon(Icons.logout, color: AppColors.textSecondary),
            ),
        ],
      ),
    );
  }

  Widget _buildIncomingCallBanner() {
    final offer = _incomingCallOffer;
    if (offer == null) {
      return const SizedBox.shrink();
    }
    final isVideo = offer.callType == 'video';
    final callLabel = isVideo ? 'Appel vidéo entrant' : 'Appel audio entrant';
    final subtitle =
        '${offer.callerName} • ${_chatDayLabel(offer.sentAt)} ${_chatClockLabel(offer.sentAt)}';

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.symmetric(
        horizontal: AppSpacing.s12,
        vertical: AppSpacing.s8,
      ),
      decoration: const BoxDecoration(
        color: Color(0xFFFFF7ED),
        border: Border(bottom: BorderSide(color: Color(0xFFFED7AA))),
      ),
      child: Wrap(
        spacing: AppSpacing.s10,
        runSpacing: AppSpacing.s8,
        crossAxisAlignment: WrapCrossAlignment.center,
        children: [
          Container(
            padding: const EdgeInsets.all(AppSpacing.s8),
            decoration: BoxDecoration(
              color: AppColors.warning.withValues(alpha: 0.14),
              borderRadius: BorderRadius.circular(12),
            ),
            child: Icon(
              isVideo ? Icons.videocam_rounded : Icons.call_rounded,
              color: const Color(0xFFB45309),
              size: 18,
            ),
          ),
          ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 520),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  callLabel,
                  style: const TextStyle(
                    color: Color(0xFF7C2D12),
                    fontWeight: FontWeight.w900,
                    fontSize: 13,
                  ),
                ),
                Text(
                  subtitle,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: Color(0xFF9A3412),
                    fontWeight: FontWeight.w700,
                    fontSize: 12,
                  ),
                ),
              ],
            ),
          ),
          OutlinedButton.icon(
            onPressed: _rejectIncomingCallOffer,
            icon: const Icon(Icons.call_end_outlined, size: 16),
            label: const Text('Refuser'),
            style: OutlinedButton.styleFrom(
              foregroundColor: AppColors.error,
              side: const BorderSide(color: Color(0xFFFCA5A5)),
            ),
          ),
          FilledButton.icon(
            onPressed: _acceptIncomingCallOffer,
            icon: const Icon(Icons.call, size: 16),
            label: const Text('Accepter'),
            style: FilledButton.styleFrom(
              backgroundColor: const Color(0xFF15803D),
              foregroundColor: Colors.white,
            ),
          ),
        ],
      ),
    );
  }

