  Widget _buildHeaderNotificationButton(int notificationCount) {
    return Stack(
      clipBehavior: Clip.none,
      children: [
        Container(
          decoration: BoxDecoration(
            color: _surfaceSlate,
            borderRadius: BorderRadius.circular(12),
