  BoxShadow _softAccentShadow(
    Color color, {
    double alpha = 0.1,
    double blurRadius = 14,
    double offsetY = 6,
  }) {
    return BoxShadow(
      color: color.withValues(alpha: alpha),
      blurRadius: blurRadius,
      offset: Offset(0, offsetY),
    );
  }

