  Widget _buildCompactMetricGrid({
    required List<({String label, String value, String caption, Color color})>
    items,
    int maxColumns = 4,
  }) {
    if (items.isEmpty) {
      return const SizedBox.shrink();
    }
    return LayoutBuilder(
      builder: (context, constraints) {
        final width = constraints.maxWidth;
        final crossAxisCount = width >= 1180
            ? maxColumns
            : width >= 900
            ? math.min(maxColumns, 5)
            : width >= 720
            ? math.min(maxColumns, 4)
            : width >= 560
            ? math.min(maxColumns, 3)
            : 2;
        final aspectRatio = width >= 1180
            ? 4.2
            : width >= 900
            ? 3.2
            : width >= 720
            ? 2.65
            : width >= 560
            ? 2.2
            : 1.95;
        return GridView.count(
          crossAxisCount: crossAxisCount,
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          childAspectRatio: aspectRatio,
          crossAxisSpacing: 8,
          mainAxisSpacing: 8,
          children: items
              .map(
                (item) => _buildCompactMetricTile(
                  label: item.label,
                  value: item.value,
                  caption: item.caption,
                  color: item.color,
                ),
              )
              .toList(),
        );
      },
    );
  }

  Widget _buildCompactMetricTile({
    required String label,
    required String value,
    required String caption,
    required Color color,
  }) {
    return Container(
      padding: AppUiTokens.metricPadding,
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [Colors.white, color.withValues(alpha: 0.06)],
        ),
        borderRadius: BorderRadius.circular(AppUiTokens.metricRadius),
        border: Border.all(color: Colors.white.withValues(alpha: 0.95)),
        boxShadow: [
          _softAccentShadow(color, alpha: 0.045, blurRadius: 6, offsetY: 1),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Row(
            children: [
              Container(
                width: 8,
                height: 8,
                decoration: BoxDecoration(color: color, shape: BoxShape.circle),
              ),
              const SizedBox(width: AppSpacing.s6),
              Expanded(
                child: Text(
                  label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: AppColors.textSecondary,
                    fontWeight: FontWeight.w800,
                    fontSize: 9.5,
                    height: 1.0,
                  ),
                ),
              ),
            ],
          ),
          Text(
            value,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: GoogleFonts.baloo2(
              color: color,
              fontWeight: FontWeight.w800,
              fontSize: 17,
              height: 0.95,
            ),
          ),
          Text(
            caption,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              color: AppColors.textMuted,
              fontWeight: FontWeight.w700,
              fontSize: 9,
              height: 1.0,
            ),
          ),
        ],
      ),
    );
  }

