  Widget _buildInseminationOutcomeCharts({
    required int successCount,
    required int failedCount,
    required int pendingCount,
    required int successRate,
  }) {
    final total = successCount + failedCount + pendingCount;
    final failedOrPendingCount = failedCount + pendingCount;

    return _buildSectionCard(
      title: 'Diagrammes IA réussie / pas réussie',
      subtitle: 'Répartition des issues d\'insémination',
      child: LayoutBuilder(
        builder: (context, constraints) {
          final isWide = constraints.maxWidth > 860;
          final donut = _buildOutcomeDonutChart(
            successCount: successCount,
            failedCount: failedCount,
            pendingCount: pendingCount,
            total: total,
          );

          final detail = Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _buildOutcomeBar(
                label: 'Réussie',
                value: successCount,
                total: total,
                color: const Color(0xFF15803D),
              ),
              _buildOutcomeBar(
                label: 'Pas réussie',
                value: failedCount,
                total: total,
                color: AppColors.error,
              ),
              _buildOutcomeBar(
                label: 'En attente',
                value: pendingCount,
                total: total,
                color: const Color(0xFFB45309),
              ),
              const SizedBox(height: AppSpacing.s10),
              Text(
                'Taux de réussite (dossiers clôturés): $successRate% '
                '($successCount réussies / ${successCount + failedCount})',
                style: const TextStyle(
                  fontWeight: FontWeight.w700,
                  color: AppColors.textSecondary,
                ),
              ),
              const SizedBox(height: AppSpacing.s4),
              Text(
                'Total pas réussie + en attente: $failedOrPendingCount',
                style: const TextStyle(
                  fontSize: 12,
                  color: AppColors.textMuted,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          );

          if (isWide) {
            return Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                donut,
                const SizedBox(width: AppSpacing.s24),
                Expanded(child: detail),
              ],
            );
          }

          return Column(
            children: [
              donut,
              const SizedBox(height: AppSpacing.s16),
              detail,
            ],
          );
        },
      ),
    );
  }

  Widget _buildOutcomeDonutChart({
    required int successCount,
    required int failedCount,
    required int pendingCount,
    required int total,
  }) {
    return SizedBox(
      width: 190,
      child: AspectRatio(
        aspectRatio: 1,
        child: Stack(
          alignment: Alignment.center,
          children: [
            CustomPaint(
              size: const Size.square(190),
              painter: _OutcomeDonutPainter(
                total: total.toDouble(),
                segments: [
                  _OutcomeSegment(
                    value: successCount.toDouble(),
                    color: const Color(0xFF15803D),
                  ),
                  _OutcomeSegment(
                    value: failedCount.toDouble(),
                    color: AppColors.error,
                  ),
                  _OutcomeSegment(
                    value: pendingCount.toDouble(),
                    color: const Color(0xFFB45309),
                  ),
                ],
              ),
            ),
            Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  '$total',
                  style: const TextStyle(
                    fontSize: 32,
                    fontWeight: FontWeight.w900,
                    color: AppColors.textPrimary,
                  ),
                ),
                const Text(
                  'IA totales',
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: AppColors.textMuted,
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildOutcomeBar({
    required String label,
    required int value,
    required int total,
    required Color color,
  }) {
    final ratio = total == 0 ? 0.0 : value / total;
    final percent = (ratio * 100).round();

    return Padding(
      padding: const EdgeInsets.only(bottom: AppSpacing.s10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                label,
                style: const TextStyle(
                  fontWeight: FontWeight.w700,
                  color: AppColors.textSecondary,
                ),
              ),
              Text(
                '$value ($percent%)',
                style: const TextStyle(
                  fontWeight: FontWeight.w800,
                  color: AppColors.textSecondary,
                ),
              ),
            ],
          ),
          const SizedBox(height: AppSpacing.s6),
          ClipRRect(
            borderRadius: BorderRadius.circular(999),
            child: LinearProgressIndicator(
              minHeight: 10,
              value: ratio,
              backgroundColor: color.withValues(alpha: 0.16),
              valueColor: AlwaysStoppedAnimation<Color>(color),
            ),
          ),
        ],
      ),
    );
  }

