  List<_OperationalTaskItem> _buildOperationalTasks() {
    final tasks = <_OperationalTaskItem>[];

    void addTask({
      required String id,
      required DateTime dueDate,
      required String module,
      required String title,
      required String responsible,
      required _ActionPriority priority,
    }) {
      tasks.add(
        _OperationalTaskItem(
          id: id,
          dueDate: _normalizeDate(dueDate),
          module: module,
          title: title,
          responsible: responsible,
          priority: priority,
          done: _taskDoneById[id] ?? false,
        ),
      );
    }

    for (final ia in _inseminations) {
      final ref = '${ia.sowCode}-${ia.boarCode}-${_formatDate(ia.dose1Date)}';
      if (!_isSuccessfulStatus(ia.status) && !_isFailedStatus(ia.status)) {
        final j21 = _expectedHeatReturnDate(ia);
        final j28 = _expectedPregnancyCheckDate(ia);
        final j35 = ia.dose1Date.add(const Duration(days: 35));
        addTask(
          id: 'TASK-IA-J21-$ref',
          dueDate: j21,
          module: 'Reproduction',
          title: 'Contrôle retour chaleur J21 - ${ia.sowCode}',
          responsible: ia.inseminator,
          priority: _priorityFromDueDate(j21),
        );
        addTask(
          id: 'TASK-IA-J28-$ref',
          dueDate: j28,
          module: 'Reproduction',
          title: 'Diagnostic gestation J28 - ${ia.sowCode}',
          responsible: ia.inseminator,
          priority: _priorityFromDueDate(j28),
        );
        addTask(
          id: 'TASK-IA-J35-$ref',
          dueDate: j35,
          module: 'Reproduction',
          title: 'Validation gestation J35 - ${ia.sowCode}',
          responsible: ia.inseminator,
          priority: _priorityFromDueDate(j35),
        );
      }
      if (_isSuccessfulStatus(ia.status)) {
        final j114 = _expectedFarrowingDate(ia);
        addTask(
          id: 'TASK-IA-J114-$ref',
          dueDate: j114,
          module: 'Maternité',
          title: 'Préparer mise-bas J114 - ${ia.sowCode}',
          responsible: _firstUserNameByRole(Roles.breeder),
          priority: _priorityFromDueDate(j114),
        );
      }
    }

    for (final record in _pigletCareRecords) {
      if (record.nextDate == null) {
        continue;
      }
      final taskId =
          'TASK-PC-${record.id}-${_formatDate(record.nextDate!)}-${record.eventType}';
      addTask(
        id: taskId,
        dueDate: record.nextDate!,
        module: 'Porcelets',
        title: 'Rappel ${record.eventType} - ${record.groupName}',
        responsible: record.responsible,
        priority: _priorityFromDueDate(record.nextDate!),
      );
    }

    for (final health in _healthRecords) {
      if (health.nextDate == null) {
        continue;
      }
      final taskId =
          'TASK-H-${health.id}-${_formatDate(health.nextDate!)}-${health.eventType}';
      addTask(
        id: taskId,
        dueDate: health.nextDate!,
        module: 'Santé',
        title:
            '${health.eventType} ${health.animalType} ${health.animalCode} (${health.product})',
        responsible: health.responsible,
        priority: _priorityFromDueDate(health.nextDate!),
      );
    }

    for (final farrowing in _farrowingRecords) {
      final weaningDate = farrowing.farrowingDate.add(const Duration(days: 28));
      addTask(
        id: 'TASK-FAR-SEVRAGE-${farrowing.id}-${_formatDate(weaningDate)}',
        dueDate: weaningDate,
        module: 'Maternité',
        title: 'Sevrage portée ${farrowing.sowCode}',
        responsible: farrowing.responsible,
        priority: _priorityFromDueDate(weaningDate),
      );
      if (farrowing.preWeaningDeaths > 0 ||
          farrowing.majorIssue.trim().isNotEmpty) {
        final reviewDate = farrowing.farrowingDate.add(const Duration(days: 1));
        addTask(
          id: 'TASK-FAR-REVUE-${farrowing.id}-${_formatDate(reviewDate)}',
          dueDate: reviewDate,
          module: 'Maternité',
          title: 'Revue pertes néonatales ${farrowing.sowCode}',
          responsible: _firstUserNameByRole(Roles.vet),
          priority: _ActionPriority.high,
        );
      }
    }

    tasks.sort((a, b) {
      final byDone = a.done == b.done
          ? 0
          : (a.done ? 1 : -1); // open tasks first
      if (byDone != 0) {
        return byDone;
      }
      return a.dueDate.compareTo(b.dueDate);
    });
    return tasks;
  }

  void _toggleOperationalTask(_OperationalTaskItem task, bool done) {
    setState(() => _taskDoneById[task.id] = done);
    _addAuditLog(
      module: 'TASKS',
      action: done ? 'TASK_DONE' : 'TASK_REOPEN',
      detail: '${task.module} • ${task.title}',
      severity: done ? 'INFO' : 'WARN',
    );
    _persistState();
  }

  Widget _buildOperationalTasksSection(List<_OperationalTaskItem> tasks) {
    final rows = tasks
        .take(20)
        .map(
          (task) => DataRow(
            cells: [
              DataCell(Text(_formatDate(task.dueDate))),
              DataCell(Text(task.module)),
              DataCell(
                Text(
                  task.title,
                  style: TextStyle(
                    fontWeight: task.done ? FontWeight.w500 : FontWeight.w700,
                    decoration: task.done
                        ? TextDecoration.lineThrough
                        : TextDecoration.none,
                  ),
                ),
              ),
              DataCell(Text(task.responsible)),
              DataCell(_buildPriorityBadge(task.priority)),
              DataCell(
                Checkbox(
                  value: task.done,
                  onChanged: (value) {
                    if (value == null) {
                      return;
                    }
                    _toggleOperationalTask(task, value);
                  },
                ),
              ),
            ],
          ),
        )
        .toList();

    return _buildDataTableSection(
      title: 'Tâches opérationnelles (terrain)',
      subtitle:
          'Pilotage exécution: J21/J28/J35/J114, rappels santé et prise en charge porcelets',
      emptyMessage: 'Aucune tâche générée.',
      columns: const [
        DataColumn(label: Text('ÉCHÉANCE')),
        DataColumn(label: Text('MODULE')),
        DataColumn(label: Text('ACTION')),
        DataColumn(label: Text('RESPONSABLE')),
        DataColumn(label: Text('PRIORITÉ')),
        DataColumn(label: Text('FAIT')),
      ],
      rows: rows,
    );
  }

  String _tabForTaskModule(String module) {
    final normalized = _normalizeLookup(module);
    if (normalized.contains('sante')) {
      return AppTabs.health;
    }
    if (normalized.contains('reproduction')) {
      return AppTabs.inseminations;
    }
    if (normalized.contains('maternite') || normalized.contains('porcelet')) {
      return AppTabs.elevage;
    }
    return AppTabs.dashboard;
  }

  List<_RoleOperationalAction> _buildRoleOperationalActions() {
    final now = _currentDate();
    final periodEnd = now.add(Duration(days: _globalPilotWindowDays() - 1));
    final role = _currentUser.role;
    final actions = <_RoleOperationalAction>[];

    bool withinWindow(DateTime dueDate) {
      if (dueDate.isBefore(now)) {
        return true;
      }
      return !dueDate.isAfter(periodEnd);
    }

    bool shouldKeepByUrgency(_OperationalTaskItem task) {
      if (!_globalPilotAlertsOnly) {
        return true;
      }
      final isOverdue = task.dueDate.isBefore(now);
      return isOverdue || task.priority == _ActionPriority.high;
    }

    bool matchRole(_OperationalTaskItem task) {
      final module = _normalizeLookup(task.module);
      final title = _normalizeLookup(task.title);
      switch (role) {
        case Roles.breeder:
          return module.contains('maternite') ||
              module.contains('porcelet') ||
              title.contains('mise-bas') ||
              title.contains('sevrage');
        case Roles.inseminator:
          return module.contains('reproduction') ||
              title.contains('diagnostic') ||
              title.contains('j21') ||
              title.contains('j28') ||
              title.contains('j35');
        case Roles.labTechnician:
          return false;
        case Roles.vet:
          return module.contains('sante') ||
              title.contains('revue pertes') ||
              title.contains('traitement') ||
              title.contains('vaccin');
        case Roles.admin:
        default:
          return true;
      }
    }

    final tasks = _buildOperationalTasks();
    for (final task in tasks) {
      if (task.done) {
        continue;
      }
      if (!withinWindow(task.dueDate)) {
        continue;
      }
      if (!shouldKeepByUrgency(task)) {
        continue;
      }
      if (!matchRole(task)) {
        continue;
      }
      actions.add(
        _RoleOperationalAction(
          id: task.id,
          dueDate: task.dueDate,
          title: task.title,
          detail: '${task.module} • ${task.responsible}',
          priority: task.priority,
          tabId: _tabForTaskModule(task.module),
          completable: true,
        ),
      );
    }

    if (role == Roles.labTechnician || role == Roles.admin) {
      for (final boar in _boars) {
        final lot = boar.preparedSemenLotNumber.trim();
        if (lot.isEmpty) {
          continue;
        }
        final hasControl = _semenQualityRecords.any(
          (record) => _normalizeLookup(record.lotCode) == _normalizeLookup(lot),
        );
        if (hasControl) {
          continue;
        }
        actions.add(
          _RoleOperationalAction(
            id: 'LAB-CONTROL-$lot',
            dueDate: now,
            title: 'Contrôle labo manquant sur lot $lot',
            detail: '${boar.code} • ${boar.name}',
            priority: _ActionPriority.high,
            tabId: AppTabs.inseminations,
            completable: false,
          ),
        );
      }

      for (final record in _semenQualityRecords) {
        if (!withinWindow(_normalizeDate(record.collectionDate))) {
          continue;
        }
        final status = _semenQualityStatus(record);
        if (status == 'Conforme') {
          continue;
        }
        final priority = status == 'Critique'
            ? _ActionPriority.high
            : _ActionPriority.medium;
        if (_globalPilotAlertsOnly && priority != _ActionPriority.high) {
          continue;
        }
        actions.add(
          _RoleOperationalAction(
            id: 'LAB-REVIEW-${record.id}',
            dueDate: _normalizeDate(record.collectionDate),
            title: 'Revue lot ${record.lotCode} ($status)',
            detail:
                '${record.boarCode} • motilité ${record.motilityPercent.toStringAsFixed(0)}%',
            priority: priority,
            tabId: AppTabs.inseminations,
            completable: false,
          ),
        );
      }
    }

    actions.sort((a, b) {
      final aUrgency = a.priority.index;
      final bUrgency = b.priority.index;
      if (aUrgency != bUrgency) {
        return aUrgency.compareTo(bUrgency);
      }
      return a.dueDate.compareTo(b.dueDate);
    });
    return actions.take(8).toList();
  }

  Widget _buildRoleActionCenterCard() {
    final actions = _buildRoleOperationalActions();
    final roleLabel = _roleLabelForUi(_currentUser.role);
    final today = _currentDate();

    return _buildSectionCard(
