          ? _buildEmptyState(
              _uiLabel(
                fr: 'Aucune action prioritaire pour $roleLabel dans la période sélectionnée.',
                mg: 'Tsy misy asa maika ho an\'i $roleLabel ao anatin\'ny vanim-potoana voafidy.',
              ),
            )
          : ListView.separated(
              shrinkWrap: true,
