  String _messengerRealtimeStatusLabel() {
    if (!_isCloudSyncAvailable()) {
      return 'Mode local';
    }
    if (_firebaseAuthUid().isEmpty) {
      return 'Connexion…';
    }
    if (!_cloudSyncActive) {
      return 'Synchronisation…';
    }
    return 'Temps réel actif';
  }

  Color _messengerRealtimeStatusColor() {
    if (!_isCloudSyncAvailable()) {
      return AppColors.warning;
    }
    if (_firebaseAuthUid().isEmpty || !_cloudSyncActive) {
      return const Color(0xFFF97316);
    }
    return const Color(0xFF4ADE80);
  }

  Widget _buildMessengerMobileExperience({
    required List<_ChatConversationSummary> conversations,
    required _ChatConversationSummary activeConversation,
    required List<ChatMessage> messages,
  }) {
    if (_isMobileMessengerThreadOpen) {
      return _buildMessengerMobileThreadScreen(
        activeConversation: activeConversation,
        messages: messages,
      );
    }
    return _buildMessengerMobileChatListScreen(
      conversations: conversations,
      activeConversationId: activeConversation.id,
    );
  }

