  Widget _buildMessengerThread({
    required _ChatConversationSummary activeConversation,
    required List<ChatMessage> messages,
    required double maxHeight,
    bool showBackButton = false,
    VoidCallback? onBack,
    bool mobile = false,
  }) {
    final screenWidth = MediaQuery.of(context).size.width;
    final maxBubbleWidth = mobile ? math.max(220.0, screenWidth * 0.76) : 440.0;
    final borderRadius = mobile ? 18.0 : 22.0;
    final visibleMessages = _visibleMessagesForConversation(
      activeConversation.id,
      messages,
    );
    final hiddenMessagesCount = _hiddenMessageCountForConversation(
      activeConversation.id,
      messages,
    );

    return Container(
      height: maxHeight,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(borderRadius),
        border: Border.all(color: AppColors.borderLight),
        boxShadow: const [
          BoxShadow(
            color: Color(0x110F172A),
            blurRadius: 20,
            offset: Offset(0, 10),
          ),
        ],
      ),
      child: Column(
        children: [
          Container(
            padding: const EdgeInsets.symmetric(
              horizontal: AppSpacing.s10,
              vertical: AppSpacing.s10,
            ),
            decoration: BoxDecoration(
              gradient: const LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
                colors: [AppColors.primaryDark, AppColors.primary],
              ),
              borderRadius: BorderRadius.only(
                topLeft: Radius.circular(borderRadius),
                topRight: Radius.circular(borderRadius),
              ),
            ),
            child: Row(
              children: [
                if (showBackButton)
                  IconButton(
                    tooltip: 'Retour',
                    onPressed:
                        onBack ??
                        () {
                          setState(() => _isMobileMessengerThreadOpen = false);
                        },
                    icon: const Icon(
                      Icons.arrow_back_ios_new_rounded,
                      color: Colors.white,
                      size: 18,
                    ),
                  ),
                CircleAvatar(
                  radius: 18,
                  backgroundColor: Colors.white.withValues(alpha: 0.18),
                  child: Text(
                    activeConversation.avatarLabel,
                    style: const TextStyle(
                      color: Colors.white,
                      fontWeight: FontWeight.w800,
                      fontSize: 12,
                    ),
                  ),
                ),
                const SizedBox(width: AppSpacing.s10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        activeConversation.title,
                        style: TextStyle(
                          fontWeight: FontWeight.w800,
                          color: Colors.white,
                          fontSize: mobile ? 14 : 15,
                        ),
                      ),
                      Text(
                        _chatThreadSubtitle(activeConversation),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: Colors.white.withValues(alpha: 0.84),
                          fontSize: 12,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      const SizedBox(height: AppSpacing.s2),
                      Row(
                        children: [
                          Icon(
                            Icons.circle,
                            size: 8,
                            color: _messengerRealtimeStatusColor(),
                          ),
                          const SizedBox(width: AppSpacing.s4),
                          Expanded(
                            child: Text(
                              _messengerRealtimeStatusLabel(),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: Colors.white.withValues(alpha: 0.82),
                                fontSize: 10,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
                if (!activeConversation.isGroup)
                  IconButton(
                    tooltip: 'Appel audio',
                    onPressed: () =>
                        _startChatCall(activeConversation.id, 'audio'),
                    icon: const Icon(Icons.call_outlined, color: Colors.white),
                  ),
                if (!activeConversation.isGroup)
                  IconButton(
                    tooltip: 'Appeler numéro externe',
                    onPressed: () =>
                        _callExternalForConversation(activeConversation.id),
                    icon: const Icon(
                      Icons.phone_in_talk_outlined,
                      color: Colors.white,
                    ),
                  ),
                if (!activeConversation.isGroup)
                  IconButton(
                    tooltip: 'Appel vidéo',
                    onPressed: () =>
                        _startChatCall(activeConversation.id, 'video'),
                    icon: const Icon(
                      Icons.videocam_outlined,
                      color: Colors.white,
                    ),
                  ),
                IconButton(
                  tooltip: 'Mode appel mondial',
                  onPressed: _openGlobalCallHub,
                  icon: const Icon(Icons.public_rounded, color: Colors.white),
                ),
              ],
            ),
          ),
          Expanded(
            child: Container(
              decoration: const BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [Color(0xFFF5FBFA), Color(0xFFEEF7F6)],
                ),
              ),
              child: messages.isEmpty
                  ? _buildEmptyState(
                      'Aucun message pour cette conversation. Écrivez le premier message.',
                    )
                  : ListView.builder(
                      padding: EdgeInsets.symmetric(
                        horizontal: mobile ? AppSpacing.s8 : AppSpacing.s12,
                        vertical: AppSpacing.s12,
                      ),
                      itemCount:
                          visibleMessages.length +
                          (hiddenMessagesCount > 0 ? 1 : 0),
                      itemBuilder: (context, index) {
                        if (hiddenMessagesCount > 0 && index == 0) {
                          return Padding(
                            padding: const EdgeInsets.only(
                              bottom: AppSpacing.s8,
                            ),
                            child: Center(
                              child: OutlinedButton.icon(
                                onPressed: () =>
                                    _loadOlderMessagesForConversation(
                                      activeConversation.id,
                                    ),
                                icon: const Icon(
                                  Icons.expand_less_rounded,
                                  size: 16,
                                ),
                                label: Text(
                                  'Charger $hiddenMessagesCount message(s) plus ancien(s)',
                                ),
                              ),
                            ),
                          );
                        }
                        final offset = hiddenMessagesCount > 0 ? 1 : 0;
                        final visibleIndex = index - offset;
                        final message = visibleMessages[visibleIndex];
                        final previous = visibleIndex > 0
                            ? visibleMessages[visibleIndex - 1]
                            : null;
                        final showDateChip =
                            previous == null ||
                            !_isSameDate(previous.sentAt, message.sentAt);
                        final isMine = message.senderId == _currentUser.id;
                        final showSender =
                            !isMine && activeConversation.isGroup;
                        final readByOthers = message.readByUserIds.any(
                          (userId) => userId != message.senderId,
                        );

                        return Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            if (showDateChip) ...[
                              _buildMessengerDateChip(message.sentAt),
