  bool _canAddForTab(String tabId) {
    if (!_canAccessTab(tabId)) {
      return false;
    }
    if (!_canCurrentUserModifyData()) {
      return false;
    }
    return !const {
      AppTabs.users,
      AppTabs.administration,
      AppTabs.profile,
      AppTabs.messenger,
      AppTabs.services,
      AppTabs.commercial,
      AppTabs.logiciel,
    }.contains(tabId);
  }

