      context: context,
      builder: (context) {
        return SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              ListTile(
                leading: const Icon(LucideIcons.badgeInfo),
                title: const Text('Ajouter un verrat'),
                onTap: () {
                  Navigator.of(context).pop();
                  _showAddBoarDialog();
