                      const SizedBox(height: AppSpacing.s12),
                      _dialogField(groupNameCtrl, 'Nom portée / groupe *'),
                      DropdownButtonFormField<String>(
                        initialValue: selectedEventType,
                        decoration: const InputDecoration(
                          labelText: 'Type soin *',
                          border: OutlineInputBorder(),
