                ElevatedButton(
                  onPressed: () {
                    final groupName = groupNameCtrl.text.trim();
                    final eventDate = _tryParseDate(eventDateCtrl.text.trim());
                    final responsible = responsibleCtrl.text.trim();
                    final details = detailsCtrl.text.trim();
                    DateTime? nextDate;

                    if (groupName.isEmpty ||
