  String _topBreedFromBoars() {
    if (_boars.isEmpty) {
      return '-';
    }
    final counts = <String, int>{};
    for (final boar in _boars) {
      counts[boar.breed] = (counts[boar.breed] ?? 0) + 1;
    }
    return counts.entries.reduce((a, b) => a.value >= b.value ? a : b).key;
  }

  String _topBreedFromSows() {
    if (_sows.isEmpty) {
      return '-';
    }
    final counts = <String, int>{};
    for (final sow in _sows) {
      counts[sow.breed] = (counts[sow.breed] ?? 0) + 1;
    }
    return counts.entries.reduce((a, b) => a.value >= b.value ? a : b).key;
  }

  String _formatAmount(double amount) {
    return NumberFormat.currency(
      locale: 'fr_FR',
      symbol: 'Ar ',
      decimalDigits: 0,
    ).format(amount);
  }

  String _formatCompactAmount(double amount) {
    if (amount.abs() >= 1000000) {
      final millions = amount / 1000000;
      final digits = millions.abs() >= 10 ? 0 : 1;
      return '${millions.toStringAsFixed(digits)} M Ar';
    }
    if (amount.abs() >= 1000) {
      return '${(amount / 1000).round()} k Ar';
    }
    return _formatAmount(amount);
  }

  String _newId(String prefix) {
    return '$prefix-${_cloudClientId.replaceAll('CLIENT-', '')}-${DateTime.now().microsecondsSinceEpoch}';
  }

  double? _tryParseAmount(String rawValue) {
    final normalized = rawValue
        .trim()
        .replaceAll(' ', '')
        .replaceAll("'", '')
        .replaceAll(',', '.');
    if (normalized.isEmpty) {
      return null;
    }
    return double.tryParse(normalized);
  }

