  Future<void> _deleteUser(String userId) async {
    if (!_ensureCanModifyData(action: 'supprimer un utilisateur')) {
      return;
    }
    final index = _users.indexWhere((user) => user.id == userId);
    if (index < 0) {
      return;
    }
    final user = _users[index];

    if (user.id == _currentUser.id) {
      _showError('Impossible de supprimer votre propre compte actif.');
      return;
    }

    final adminCount = _users.where((item) => item.role == Roles.admin).length;
    if (user.role == Roles.admin && adminCount <= 1) {
      _showError('Impossible de supprimer le dernier administrateur.');
      return;
    }

    final assignedInBoars = _boars.any((boar) => boar.breederId == user.id);
    final assignedInSows = _sows.any((sow) => sow.breederId == user.id);
    if (assignedInBoars || assignedInSows) {
      _showError(
        'Utilisateur affecté à des animaux. Réaffectez les verrats/truies avant suppression.',
      );
      return;
    }

    final confirmed = await _confirmDeletion(
      title: 'Supprimer ${user.name} ?',
      message:
          'Compte ${user.login} (${user.role}). Cette suppression est définitive.',
    );
    if (!confirmed || !mounted) {
      return;
    }
    _addAuditLog(
      module: 'USERS',
      action: 'DELETE_USER',
      detail: 'Suppression utilisateur ${user.code} (${user.role})',
      severity: 'WARN',
    );
    setState(() => _users.removeAt(index));
    _pendingUserUpsertIds.remove(user.id);
    _pendingUserDeleteIds.add(user.id);
    _persistState(immediateCloudPush: true);
    unawaited(_deleteUserRecordFromCloud(user.id));
    _showInfo('Utilisateur supprimé.');
  }

  bool _isDuplicateUserCode(String code, {String? ignoreUserId}) {
    final normalized = code.trim().toLowerCase();
    if (normalized.isEmpty) {
      return false;
    }
    return _users.any(
      (user) =>
          user.id != ignoreUserId &&
          user.code.trim().toLowerCase() == normalized,
    );
  }

  bool _isDuplicateUserLogin(String login, {String? ignoreUserId}) {
    final normalized = login.trim().toLowerCase();
    if (normalized.isEmpty) {
      return false;
    }
    return _users.any(
      (user) =>
          user.id != ignoreUserId &&
          user.login.trim().toLowerCase() == normalized,
    );
  }

  bool _isStrongPassword(String password) {
    if (password.length < 8) {
      return false;
    }
    final hasLetter = RegExp(r'[A-Za-z]').hasMatch(password);
    final hasDigit = RegExp(r'\d').hasMatch(password);
    return hasLetter && hasDigit;
  }

  bool _isHashedPassword(String value) {
    return value.startsWith(_passwordHashPrefix) &&
        value.length > _passwordHashPrefix.length + 16;
  }

  String _hashPassword(String password) {
    final hash = sha256.convert(utf8.encode(password)).toString();
    return '$_passwordHashPrefix$hash';
  }

  bool _verifyPassword(UserProfile user, String password) {
    final stored = user.password;
    if (_isHashedPassword(stored)) {
      return stored == _hashPassword(password);
    }
    return stored == password;
  }

  bool _migrateLegacyPasswords() {
    var changed = false;
    for (var i = 0; i < _users.length; i++) {
      final user = _users[i];
      if (_isHashedPassword(user.password)) {
        continue;
      }
      _users[i] = UserProfile(
        id: user.id,
        code: user.code,
        name: user.name,
        role: user.role,
        avatar: user.avatar,
        address: user.address,
        contact: user.contact,
        fokontany: user.fokontany,
        commune: user.commune,
        district: user.district,
        region: user.region,
        bio: user.bio,
        profileImageBase64: user.profileImageBase64,
        coverImageBase64: user.coverImageBase64,
        login: user.login,
        password: _hashPassword(user.password),
      );
      changed = true;
    }
    if (changed) {
      _currentUser = _findUserById(_currentUser.id) ?? _currentUser;
    }
    return changed;
  }

  void _addAuditLog({
    required String module,
    required String action,
    required String detail,
    String severity = 'INFO',
    UserProfile? actor,
  }) {
    final user = actor ?? _currentUser;
    final entry = AuditLogEntry(
      id: _newId('LOG'),
      timestamp: DateTime.now(),
      actorCode: user.code,
      actorName: user.name,
      module: module,
      action: action,
      detail: detail,
      severity: severity,
    );
    setState(() {
      _auditLogs.insert(0, entry);
      if (_auditLogs.length > 500) {
        _auditLogs.removeRange(500, _auditLogs.length);
      }
    });
    unawaited(_publishFieldAuditEvent(entry, user));
  }

  Future<void> _publishFieldAuditEvent(
    AuditLogEntry entry,
    UserProfile actor,
  ) async {
    if (!_isAuthenticated) {
      return;
    }
    try {
      await _ensureCloudBackendReady();
      await _ensureFirebaseAuthSessionReady();
      final authUid = _firebaseAuthUid();
      if (authUid.isEmpty) {
        return;
      }
      await _cloudFieldEventsRef.doc(entry.id).set(<String, dynamic>{
        'id': entry.id,
        'timestamp': entry.timestamp.toUtc().toIso8601String(),
        'actorCode': entry.actorCode,
        'actorName': entry.actorName,
        'actorRole': actor.role,
        'module': entry.module,
        'action': entry.action,
        'detail': entry.detail,
        'severity': entry.severity,
        'authUid': authUid,
        'appUserId': actor.id,
        'clientId': _cloudClientId,
        'createdAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    } catch (_) {
      // Field event trace is best effort and must not block the UI.
    }
  }

  String _authStateLabel(UserProfile user) {
    return _isHashedPassword(user.password) ? 'Hashé' : 'À migrer';
  }

  String _avatarFromName(String name) {
    final clean = name.trim();
    if (clean.isEmpty) {
      return 'U';
    }
    return clean.substring(0, 1).toUpperCase();
  }

  void _disposeControllers(List<TextEditingController> controllers) {
    for (final ctrl in controllers) {
      ctrl.dispose();
    }
  }

  Boar? _findBoar(String code) {
    for (final boar in _boars) {
      if (boar.code.toLowerCase() == code.toLowerCase()) {
        return boar;
      }
    }
    return null;
  }

  Sow? _findSow(String code) {
    for (final sow in _sows) {
      if (sow.code.toLowerCase() == code.toLowerCase()) {
        return sow;
      }
    }
    return null;
  }

  String? _consanguinityIssue(String sowCode, String boarCode) {
    final sow = _findSow(sowCode);
    final boar = _findBoar(boarCode);
    if (sow == null || boar == null) {
      return null;
    }

    final boarCodeNormalized = _normalizeLookup(boar.code);
    final sowCodeNormalized = _normalizeLookup(sow.code);
    final sowSire = _normalizeLookup(sow.sireCode);
    final sowDam = _normalizeLookup(sow.damCode);
    final boarSire = _normalizeLookup(boar.sireCode);
    final boarDam = _normalizeLookup(boar.damCode);

    if (boarCodeNormalized == sowSire && sowSire.isNotEmpty) {
      return 'le verrat sélectionné est le père direct de la truie';
    }
    if (boarCodeNormalized == sowDam && sowDam.isNotEmpty) {
      return 'le verrat sélectionné est lié à la mère de la truie';
    }
    if (boarSire == sowSire && boarSire.isNotEmpty) {
      return 'la truie et le verrat partagent le même père (${sow.sireCode})';
    }
    if (boarDam == sowDam && boarDam.isNotEmpty) {
      return 'la truie et le verrat partagent la même mère (${sow.damCode})';
    }
    if (boarSire == sowCodeNormalized && boarSire.isNotEmpty) {
      return 'la truie est ascendant direct du verrat (père du verrat)';
    }
    if (boarDam == sowCodeNormalized && boarDam.isNotEmpty) {
      return 'la truie est ascendant direct du verrat (mère du verrat)';
    }
    return null;
  }

  List<UserProfile> get _breeders =>
      _users.where((user) => user.role == Roles.breeder).toList();

  List<UserProfile> get _labTechnicians =>
      _users.where((user) => user.role == Roles.labTechnician).toList();

  UserProfile? _findUserById(String id) {
    for (final user in _users) {
      if (user.id == id) {
        return user;
      }
    }
    return null;
  }

  String _directConversationId(String userIdA, String userIdB) {
    final ids = [userIdA.trim(), userIdB.trim()]..sort();
    return 'DM|${ids[0]}|${ids[1]}';
  }

  String _callSessionIdForMessage(ChatMessage message) {
    final sessionId = message.callSessionId.trim();
    if (sessionId.isNotEmpty) {
      return sessionId;
    }
    return message.id;
  }

  bool _isCallRingingStatus(String status) {
    final normalized = _normalizeLookup(status);
    if (normalized.isEmpty) {
      return false;
    }
    return normalized.contains('sonnerie') || normalized.contains('ringing');
  }

  ChatMessage? _findLatestIncomingCallInvitation() {
    final sorted = List<ChatMessage>.from(_chatMessages)
      ..sort((a, b) => b.sentAt.compareTo(a.sentAt));
    final closedSessions = <String>{};
    final now = DateTime.now();
    for (final message in sorted) {
      if (_normalizeLookup(message.messageType) != 'call') {
        continue;
      }
      if (!_isConversationVisibleForCurrentUser(message.conversationId)) {
        continue;
      }
      final sessionId = _callSessionIdForMessage(message);
      if (closedSessions.contains(sessionId)) {
        continue;
      }
      if (!_isCallRingingStatus(message.callStatus)) {
        closedSessions.add(sessionId);
        continue;
      }
      final invitationAgeMinutes = now.difference(message.sentAt).inMinutes;
      if (invitationAgeMinutes > _incomingCallMaxAgeMinutes) {
        closedSessions.add(sessionId);
        continue;
      }
      if (invitationAgeMinutes < -_incomingCallMaxAgeMinutes) {
        continue;
      }
      if (message.senderId == _currentUser.id) {
        continue;
      }
      return message;
    }
    return null;
  }

  void _playIncomingCallTone() {
    try {
      SystemSound.play(SystemSoundType.alert);
    } catch (_) {
      // Keep ringing workflow even if sound API is unavailable.
    }
  }

  void _startIncomingCallRingtone() {
    if (_incomingCallOffer == null || !_isAuthenticated) {
      return;
    }
    if (_incomingCallRingtoneTimer != null) {
      return;
    }
    _playIncomingCallTone();
    _incomingCallRingtoneTimer = Timer.periodic(const Duration(seconds: 2), (
      _,
    ) {
      if (!mounted || !_isAuthenticated || _incomingCallOffer == null) {
        _stopIncomingCallRingtone();
        return;
      }
      _playIncomingCallTone();
    });
  }

  void _stopIncomingCallRingtone() {
    _incomingCallRingtoneTimer?.cancel();
    _incomingCallRingtoneTimer = null;
  }

  void _syncIncomingCallOffer() {
    if (!mounted || !_isAuthenticated) {
      if (_incomingCallOffer != null) {
        setState(() => _incomingCallOffer = null);
      }
      _stopIncomingCallRingtone();
      return;
    }

    final incoming = _findLatestIncomingCallInvitation();
    if (incoming == null) {
      if (_incomingCallOffer != null) {
        setState(() => _incomingCallOffer = null);
      }
      _stopIncomingCallRingtone();
      return;
    }

    final sessionId = _callSessionIdForMessage(incoming);
    if (_incomingCallOffer?.sessionId == sessionId) {
      _startIncomingCallRingtone();
      return;
    }

    setState(() {
      _incomingCallOffer = _IncomingCallOffer(
        sessionId: sessionId,
        conversationId: incoming.conversationId,
        callerId: incoming.senderId,
        callerName: incoming.senderName,
        callType: incoming.callType.trim().toLowerCase() == 'video'
            ? 'video'
            : 'audio',
        transport: _callTransportWebRtc,
        roomName: '',
        sentAt: incoming.sentAt,
      );
      if (_canAccessTab(AppTabs.messenger)) {
        _activeTab = AppTabs.messenger;
        _activeChatConversationId = incoming.conversationId;
        _isMobileMessengerThreadOpen = true;
      }
    });
    _startIncomingCallRingtone();
    _showInfo(
      'Appel ${_incomingCallOffer!.callType == 'video' ? 'vidéo' : 'audio'} entrant: ${_incomingCallOffer!.callerName}',
    );
  }

  Future<void> _acceptIncomingCallOffer() async {
    final offer = _incomingCallOffer;
    if (offer == null) {
      return;
    }
    if (_isInLiveCall) {
      _showError('Un appel est déjà en cours.');
      return;
    }
    if (!_canCurrentUserPostToConversation(offer.conversationId)) {
      _showError(_teamConversationAccessError());
      return;
    }
    final callLabel = offer.callType == 'video' ? 'vidéo' : 'audio';
    _stopIncomingCallRingtone();
    setState(() {
      _incomingCallOffer = null;
      _activeChatConversationId = offer.conversationId;
      _activeTab = AppTabs.messenger;
    });

    _appendChatMessage(
      ChatMessage(
        id: _newId('MSG'),
        conversationId: offer.conversationId,
        senderId: _currentUser.id,
        senderName: _currentUser.name,
        text: 'Appel $callLabel accepté',
        sentAt: DateTime.now(),
        readByUserIds: [_currentUser.id],
        messageType: 'call',
        callType: offer.callType,
        callStatus: _callAcceptedStatus,
        callSessionId: offer.sessionId,
      ),
    );
    _addAuditLog(
      module: 'MESSAGERIE',
      action: 'ACCEPT_CALL',
      detail: 'Appel $callLabel accepté (${offer.callerName})',
    );

    int? durationSeconds;
    if (offer.transport == _callTransportLiveKit) {
      final roomName = offer.roomName.trim().isEmpty
          ? _roomNameForCallSession(offer.sessionId)
          : offer.roomName.trim();
      final service = LiveKitCallService();
      try {
        await FirebaseFirestore.instance
            .collection('porc_webrtc_signaling')
            .doc(offer.sessionId)
            .set(<String, dynamic>{
              'transport': _callTransportLiveKit,
              'roomName': roomName,
              'answer': <String, dynamic>{'type': 'accepted', 'sdp': 'livekit'},
              'answeredByAuthUid': _firebaseAuthUid(),
              'acceptedAt': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
        await service.connect(
          sessionId: offer.sessionId,
          roomName: roomName,
          participantId: _currentUser.id,
          participantName: _currentUser.name,
          enableVideo: offer.callType == 'video',
        );
      } catch (e) {
        _showError('Impossible de répondre à l\'appel LiveKit : $e');
        await service.dispose();
        return;
      }
      _activeLiveKitService = service;
      _activeCallSessionId = offer.sessionId;
      if (!mounted) {
        await service.dispose();
        return;
      }
      durationSeconds = await _showLiveKitCallScreen(
        callType: offer.callType,
        title: offer.callerName,
        service: service,
        sessionId: offer.sessionId,
        isCaller: false,
      );
    } else {
      // --- WebRTC P2P path ---
      final service = WebRTCCallService();
      try {
        await service.initialize(isVideo: offer.callType == 'video');
        await service.answerCall(offer.sessionId);
      } catch (e) {
        _showError('Impossible de répondre à l\'appel : $e');
        await service.dispose();
        return;
      }

      _activeWebRTCService = service;
      _activeCallSessionId = offer.sessionId;

      if (!mounted) {
        await service.dispose();
        return;
      }

      durationSeconds = await _showLiveCallScreen(
        callType: offer.callType,
        title: offer.callerName,
        service: service,
        sessionId: offer.sessionId,
        isCaller: false,
      );
    }
    if (!mounted) {
      return;
    }

    final callStatus = durationSeconds == null ? 'Manqué' : 'Terminé';
    final callText = durationSeconds == null
        ? 'Appel $callLabel manqué'
        : 'Appel $callLabel terminé (${_formatDuration(durationSeconds)})';
    _appendChatMessage(
      ChatMessage(
        id: _newId('MSG'),
        conversationId: offer.conversationId,
        senderId: _currentUser.id,
        senderName: _currentUser.name,
        text: callText,
        sentAt: DateTime.now(),
        readByUserIds: [_currentUser.id],
        messageType: 'call',
        callType: offer.callType,
        callStatus: callStatus,
        callDurationSeconds: durationSeconds ?? 0,
        callSessionId: offer.sessionId,
      ),
    );
    _addAuditLog(
      module: 'MESSAGERIE',
      action: durationSeconds == null ? 'MISS_CALL' : 'END_CALL',
      detail: durationSeconds == null
          ? 'Appel $callLabel manqué (${offer.callerName})'
          : 'Appel $callLabel terminé (${offer.callerName}, ${_formatDuration(durationSeconds)})',
    );
    _persistState(immediateCloudPush: true);
    _syncIncomingCallOffer();
  }

  void _rejectIncomingCallOffer() {
    final offer = _incomingCallOffer;
    if (offer == null) {
      return;
    }
    if (!_canCurrentUserPostToConversation(offer.conversationId)) {
      _showError(_teamConversationAccessError());
      return;
    }
    final callLabel = offer.callType == 'video' ? 'vidéo' : 'audio';
    _stopIncomingCallRingtone();
    setState(() => _incomingCallOffer = null);
    _appendChatMessage(
      ChatMessage(
        id: _newId('MSG'),
        conversationId: offer.conversationId,
        senderId: _currentUser.id,
        senderName: _currentUser.name,
        text: 'Appel $callLabel refusé',
        sentAt: DateTime.now(),
        readByUserIds: [_currentUser.id],
        messageType: 'call',
        callType: offer.callType,
        callStatus: _callRejectedStatus,
        callSessionId: offer.sessionId,
      ),
    );
    _addAuditLog(
      module: 'MESSAGERIE',
      action: 'REJECT_CALL',
      detail: 'Appel $callLabel refusé (${offer.callerName})',
    );
    _persistState(immediateCloudPush: true);

    // Clean up Firestore signaling document so caller detects rejection.
    try {
      FirebaseFirestore.instance
          .collection('porc_webrtc_signaling')
          .doc(offer.sessionId)
          .set(<String, dynamic>{
            'hangUp': true,
            'hangUpByAuthUid': _firebaseAuthUid(),
            'hangUpAt': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
    } catch (_) {}
  }

  bool _isTeamConversationUserAllowed(UserProfile user) {
    return user.id.trim().isNotEmpty;
  }

  bool _isTeamConversationUserIdAllowed(String userId) {
    final normalizedUserId = userId.trim();
    if (normalizedUserId.isEmpty) {
      return false;
    }
    final user = _findUserById(normalizedUserId);
    if (user == null) {
      // Keep team messages visible even if the sender profile is not yet loaded locally.
      return true;
    }
    return _isTeamConversationUserAllowed(user);
  }

  bool _canCurrentUserAccessTeamConversation() {
    return _isTeamConversationUserAllowed(_currentUser);
  }

  bool _isConversationVisibleForCurrentUser(String conversationId) {
    if (conversationId == _teamConversationId) {
      return _canCurrentUserAccessTeamConversation();
    }
    if (!conversationId.startsWith('DM|')) {
      return false;
    }
    final parts = conversationId.split('|');
    if (parts.length != 3) {
      return false;
    }
    return parts[1] == _currentUser.id || parts[2] == _currentUser.id;
  }

  int _teamConversationParticipantCount() {
    var total = 0;
    for (final user in _users) {
      if (_isTeamConversationUserAllowed(user)) {
        total++;
      }
    }
    return total;
  }

  bool _canCurrentUserPostToConversation(String conversationId) {
    if (conversationId != _teamConversationId) {
      return true;
    }
    return _canCurrentUserAccessTeamConversation();
  }

  String _teamConversationAccessError() {
    return 'Canal équipe indisponible.';
  }

  bool _isMessageReadByUser(ChatMessage message, String userId) {
    return message.readByUserIds.contains(userId.trim());
  }

  int _unreadCountForConversation(String conversationId) {
    var unread = 0;
    for (final message in _messagesForConversation(conversationId)) {
      if (message.senderId == _currentUser.id) {
        continue;
      }
      if (_isMessageReadByUser(message, _currentUser.id)) {
        continue;
      }
      unread++;
    }
    return unread;
  }

  bool _markConversationAsReadInState(String conversationId) {
    var changed = false;
    for (var i = 0; i < _chatMessages.length; i++) {
      final message = _chatMessages[i];
      if (message.conversationId != conversationId ||
          (conversationId == _teamConversationId &&
              !_isTeamConversationUserIdAllowed(message.senderId)) ||
          message.senderId == _currentUser.id ||
          _isMessageReadByUser(message, _currentUser.id)) {
        continue;
      }
      _chatMessages[i] = message.copyWith(
        readByUserIds: [...message.readByUserIds, _currentUser.id],
      );
      changed = true;
    }
    return changed;
  }

  void _markConversationAsReadDeferred(String conversationId) {
    if (_chatReadSyncScheduled ||
        _unreadCountForConversation(conversationId) == 0) {
      return;
    }
    _chatReadSyncScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) {
        _chatReadSyncScheduled = false;
        return;
      }
      var changed = false;
      setState(() {
        changed = _markConversationAsReadInState(conversationId);
        _chatReadSyncScheduled = false;
      });
      if (changed) {
        _persistState();
      }
    });
  }

  List<ChatMessage> _messagesForConversation(String conversationId) {
    final messages = _chatMessages.where((message) {
      if (message.conversationId != conversationId) {
        return false;
      }
      if (conversationId == _teamConversationId &&
          !_isTeamConversationUserIdAllowed(message.senderId)) {
        return false;
      }
      return true;
    }).toList();
    messages.sort((a, b) => a.sentAt.compareTo(b.sentAt));
    return messages;
  }

  void _seedMessageRenderWindow(String conversationId, {int? totalMessages}) {
    final normalizedConversationId = conversationId.trim();
    if (normalizedConversationId.isEmpty) {
      return;
    }
    if (_messageRenderWindowByConversation.containsKey(
      normalizedConversationId,
    )) {
      return;
    }
    final total =
        totalMessages ??
        _messagesForConversation(normalizedConversationId).length;
    final initialLimit = total <= 0
        ? _messengerRenderWindowDefault
        : math.min(total, _messengerRenderWindowDefault);
    _messageRenderWindowByConversation[normalizedConversationId] = initialLimit;
  }

  int _messageRenderWindowLimit(String conversationId, int totalMessages) {
    if (totalMessages <= 0) {
      return 0;
    }
    _seedMessageRenderWindow(conversationId, totalMessages: totalMessages);
    final stored =
        _messageRenderWindowByConversation[conversationId] ??
        _messengerRenderWindowDefault;
    final normalizedStored = math.max(_messengerRenderWindowDefault, stored);
    return math.min(totalMessages, normalizedStored);
  }

  List<ChatMessage> _visibleMessagesForConversation(
    String conversationId,
    List<ChatMessage> messages,
  ) {
    if (messages.isEmpty) {
      return const <ChatMessage>[];
    }
    final limit = _messageRenderWindowLimit(conversationId, messages.length);
    final from = math.max(0, messages.length - limit);
    return messages.sublist(from);
  }

  int _hiddenMessageCountForConversation(
    String conversationId,
    List<ChatMessage> messages,
  ) {
    if (messages.isEmpty) {
      return 0;
    }
    final limit = _messageRenderWindowLimit(conversationId, messages.length);
    return math.max(0, messages.length - limit);
  }

  void _loadOlderMessagesForConversation(String conversationId) {
    final normalizedConversationId = conversationId.trim();
    if (normalizedConversationId.isEmpty) {
      return;
    }
    final total = _messagesForConversation(normalizedConversationId).length;
    final current = _messageRenderWindowLimit(normalizedConversationId, total);
    final next = math.min(total, current + _messengerRenderWindowStep);
    if (next == current) {
      return;
    }
    setState(() {
      _messageRenderWindowByConversation[normalizedConversationId] = next;
    });
  }

  String _resolveActiveConversationId(
    List<_ChatConversationSummary> conversations,
  ) {
    for (final conversation in conversations) {
      if (conversation.id == _activeChatConversationId) {
        return conversation.id;
      }
    }
    return conversations.first.id;
  }

  List<_ChatConversationSummary> _buildChatConversationSummaries() {
    final summaries = <_ChatConversationSummary>[];
    if (_canCurrentUserAccessTeamConversation()) {
      final groupMessages = _messagesForConversation(_teamConversationId);
      final groupLast = groupMessages.isEmpty ? null : groupMessages.last;
      summaries.add(
        _ChatConversationSummary(
          id: _teamConversationId,
          title: 'Canal Équipe',
          subtitle: '${_teamConversationParticipantCount()} utilisateur(s)',
          preview: groupLast == null
              ? 'Aucun message pour le moment.'
              : _clipText(_chatMessagePreview(groupLast), 64),
          lastMessageAt: groupLast?.sentAt,
          unreadCount: _unreadCountForConversation(_teamConversationId),
          avatarLabel: 'EQ',
          avatarColor: AppColors.primaryDark,
          isGroup: true,
        ),
      );
    }

    final peers = _users.where((user) => user.id != _currentUser.id).toList();
    for (final peer in peers) {
      final conversationId = _directConversationId(_currentUser.id, peer.id);
      final messages = _messagesForConversation(conversationId);
      final last = messages.isEmpty ? null : messages.last;
      summaries.add(
        _ChatConversationSummary(
          id: conversationId,
          title: peer.name,
          subtitle: '${peer.role} • ${peer.code}',
          preview: last == null
              ? 'Démarrer la conversation'
              : _clipText(_chatMessagePreview(last), 64),
          lastMessageAt: last?.sentAt,
          unreadCount: _unreadCountForConversation(conversationId),
          avatarLabel: peer.avatar,
          avatarColor: _roleColor(peer.role),
        ),
      );
    }

    summaries.sort((a, b) {
      if (a.isGroup && !b.isGroup) {
        return -1;
      }
      if (!a.isGroup && b.isGroup) {
        return 1;
      }
      final aTime = a.lastMessageAt;
      final bTime = b.lastMessageAt;
      if (aTime == null && bTime == null) {
        return a.title.compareTo(b.title);
      }
      if (aTime == null) {
        return 1;
      }
      if (bTime == null) {
        return -1;
      }
      return bTime.compareTo(aTime);
    });

    return summaries;
  }

  void _setActiveChatConversation(String conversationId) {
    final targetConversationId = conversationId.trim().isEmpty
        ? _teamConversationId
        : conversationId.trim();
    if (targetConversationId == _teamConversationId &&
        !_canCurrentUserAccessTeamConversation()) {
      _showError(_teamConversationAccessError());
      return;
    }
    setState(() {
      _activeChatConversationId = targetConversationId;
      _seedMessageRenderWindow(
        _activeChatConversationId,
        totalMessages: _messagesForConversation(
          _activeChatConversationId,
        ).length,
      );
      _markConversationAsReadInState(_activeChatConversationId);
    });
    _persistState();
  }

  void _sendChatMessage(String conversationId) {
    final text = _chatComposerController.text.trim();
    if (text.isEmpty) {
      _showError('Écrivez un message avant d\'envoyer.');
      return;
    }

    final targetConversationId = _resolveChatConversationId(conversationId);
    if (!_canCurrentUserPostToConversation(targetConversationId)) {
      _showError(_teamConversationAccessError());
      return;
    }
    _appendChatMessage(
      ChatMessage(
        id: _newId('MSG'),
        conversationId: targetConversationId,
        senderId: _currentUser.id,
        senderName: _currentUser.name,
        text: text,
        sentAt: DateTime.now(),
        readByUserIds: [_currentUser.id],
      ),
      clearComposer: true,
    );
    _addAuditLog(
      module: 'MESSAGERIE',
      action: 'SEND_MESSAGE',
      detail:
          'Message envoyé (${targetConversationId == _teamConversationId ? 'Canal équipe' : 'conversation directe'})',
    );
    _persistState(immediateCloudPush: true);
  }

  String _resolveChatConversationId(String conversationId) {
    final normalized = conversationId.trim();
    if (normalized.isNotEmpty) {
      return normalized;
    }
    if (_canCurrentUserAccessTeamConversation()) {
      return _teamConversationId;
    }
    for (final user in _users) {
      if (user.id != _currentUser.id) {
        return _directConversationId(_currentUser.id, user.id);
      }
    }
    return _teamConversationId;
  }

  void _appendChatMessage(ChatMessage message, {bool clearComposer = false}) {
    setState(() {
      _mergeChatMessagesInState([message]);
      _activeChatConversationId = message.conversationId;
      _seedMessageRenderWindow(
        message.conversationId,
        totalMessages: _messagesForConversation(message.conversationId).length,
      );
      _markConversationAsReadInState(message.conversationId);
    });
    if (clearComposer) {
      _chatComposerController.clear();
    }
    unawaited(_publishChatMessageRealtime(message));
    _syncIncomingCallOffer();
    _persistState(immediateCloudPush: true);
  }

  Future<void> _publishChatMessageRealtime(ChatMessage message) async {
    if (!_isCloudSyncAvailable() || !_isAuthenticated) {
      return;
    }
    final authUid = _firebaseAuthUid();
    if (authUid.isEmpty || !_cloudSyncActive) {
      _scheduleChatRealtimePublishRetry(message);
      return;
    }
    final retryAttempt =
        _chatRealtimePublishAttemptsByMessageId[message.id] ?? 0;
    final payload = Map<String, dynamic>.from(_chatMessageToCloudJson(message))
      ..['sentAtMs'] = message.sentAt.toUtc().millisecondsSinceEpoch
      ..['updatedAt'] = FieldValue.serverTimestamp()
      ..['senderAuthUid'] = authUid
      ..['appUserId'] = _currentUser.id
      ..['clientId'] = _cloudClientId
      ..['retryAttempt'] = retryAttempt;
    try {
      await _cloudChatRealtimeRef
          .doc(message.id)
          .set(payload, SetOptions(merge: true));
      _clearChatRealtimePublishRetry(message.id);
    } catch (_) {
      _scheduleChatRealtimePublishRetry(message);
    }
  }

  void _clearChatRealtimePublishRetry(String messageId) {
    final normalizedMessageId = messageId.trim();
    if (normalizedMessageId.isEmpty) {
      return;
    }
    _chatRealtimePublishRetryTimers.remove(normalizedMessageId)?.cancel();
    _chatRealtimePublishAttemptsByMessageId.remove(normalizedMessageId);
  }

  void _scheduleChatRealtimePublishRetry(ChatMessage message) {
    if (!mounted || !_isAuthenticated || !_isCloudSyncAvailable()) {
      return;
    }
    final messageId = message.id.trim();
    if (messageId.isEmpty) {
      return;
    }
    final attempt =
        (_chatRealtimePublishAttemptsByMessageId[messageId] ?? 0) + 1;
    if (attempt > _chatRealtimePublishMaxRetries) {
      _clearChatRealtimePublishRetry(messageId);
      return;
    }
    _chatRealtimePublishAttemptsByMessageId[messageId] = attempt;

    _chatRealtimePublishRetryTimers.remove(messageId)?.cancel();
    final delaySeconds = math.min(
      20,
      math.max(2, math.pow(2, attempt).toInt()),
    );
    _chatRealtimePublishRetryTimers[messageId] = Timer(
      Duration(seconds: delaySeconds),
      () {
        _chatRealtimePublishRetryTimers.remove(messageId);
        unawaited(_publishChatMessageRealtime(message));
      },
    );
  }

  Future<void> _pickAndSendChatAttachment(
    String conversationId,
    String messageType,
  ) async {
    FileType pickerType = FileType.custom;
    List<String>? allowedExtensions;
    var maxBytes = _chatImageMaxBytes;
    var label = 'Pièce jointe';

    switch (messageType) {
      case 'image':
        pickerType = FileType.image;
        maxBytes = _chatImageMaxBytes;
        label = 'Image';
        break;
      case 'video':
        pickerType = FileType.custom;
        allowedExtensions = const ['mp4', 'mov', 'avi', 'mkv', 'webm'];
        maxBytes = _chatVideoMaxBytes;
        label = 'Vidéo';
        break;
      case 'audio':
        pickerType = FileType.custom;
        allowedExtensions = const ['mp3', 'wav', 'm4a', 'aac', 'ogg'];
        maxBytes = _chatAudioMaxBytes;
        label = 'Audio';
        break;
      default:
        _showError('Type de pièce jointe non supporté.');
        return;
    }

    try {
      final result = await FilePicker.platform.pickFiles(
        type: pickerType,
        allowedExtensions: allowedExtensions,
        withData: true,
        allowMultiple: false,
      );
      if (result == null || result.files.isEmpty) {
        return;
      }
      final file = result.files.single;
      final bytes = file.bytes;
      if (bytes == null || bytes.isEmpty) {
        _showError('$label invalide. Réessayez avec un autre fichier.');
        return;
      }
      if (bytes.length > maxBytes) {
        final maxLabel = _formatFileSize(maxBytes);
        _showError(
          '$label trop lourd (${_formatFileSize(bytes.length)}). Limite: $maxLabel.',
        );
        return;
      }

      final name = file.name.trim().isEmpty ? '$label.bin' : file.name.trim();
      final extension = file.extension == null
          ? _fileExtensionFromName(name)
          : file.extension!.toLowerCase();
      final mimeType = _chatMimeTypeForAttachment(
        messageType: messageType,
        extension: extension,
      );

      _sendChatAttachment(
        conversationId: conversationId,
        messageType: messageType,
        mediaBase64: base64Encode(bytes),
        mediaName: name,
        mediaMimeType: mimeType,
        mediaSizeBytes: bytes.length,
      );
    } catch (_) {
      _showError('Impossible de charger la pièce jointe.');
    }
  }

  String _fileExtensionFromName(String filename) {
    final index = filename.lastIndexOf('.');
    if (index < 0 || index >= filename.length - 1) {
      return '';
    }
    return filename.substring(index + 1).toLowerCase();
  }

  String _chatMimeTypeForAttachment({
    required String messageType,
    required String extension,
  }) {
    switch (messageType) {
      case 'image':
        switch (extension) {
          case 'jpg':
          case 'jpeg':
            return 'image/jpeg';
          case 'png':
            return 'image/png';
          case 'webp':
            return 'image/webp';
          case 'gif':
            return 'image/gif';
          default:
            return 'image/*';
        }
      case 'video':
        switch (extension) {
          case 'mp4':
            return 'video/mp4';
          case 'mov':
            return 'video/quicktime';
          case 'avi':
            return 'video/x-msvideo';
          case 'mkv':
            return 'video/x-matroska';
          case 'webm':
            return 'video/webm';
          default:
            return 'video/*';
        }
      case 'audio':
        switch (extension) {
          case 'mp3':
            return 'audio/mpeg';
          case 'wav':
            return 'audio/wav';
          case 'm4a':
            return 'audio/mp4';
          case 'aac':
            return 'audio/aac';
          case 'ogg':
            return 'audio/ogg';
          default:
            return 'audio/*';
        }
      default:
        return 'application/octet-stream';
    }
  }

  void _sendChatAttachment({
    required String conversationId,
    required String messageType,
    required String mediaBase64,
    required String mediaName,
    required String mediaMimeType,
    required int mediaSizeBytes,
  }) {
    final targetConversationId = _resolveChatConversationId(conversationId);
    if (!_canCurrentUserPostToConversation(targetConversationId)) {
      _showError(_teamConversationAccessError());
      return;
    }
    final label = switch (messageType) {
      'image' => 'Image',
      'video' => 'Vidéo',
      'audio' => 'Audio',
      _ => 'Pièce jointe',
    };

    _appendChatMessage(
      ChatMessage(
        id: _newId('MSG'),
        conversationId: targetConversationId,
        senderId: _currentUser.id,
        senderName: _currentUser.name,
        text: '$label envoyé',
        sentAt: DateTime.now(),
        readByUserIds: [_currentUser.id],
        messageType: messageType,
        mediaBase64: mediaBase64,
        mediaName: mediaName,
        mediaMimeType: mediaMimeType,
        mediaSizeBytes: mediaSizeBytes,
      ),
    );
    _addAuditLog(
      module: 'MESSAGERIE',
      action: 'SEND_MEDIA',
      detail:
          '$label envoyé (${targetConversationId == _teamConversationId ? 'Canal équipe' : 'conversation directe'})',
    );
    _persistState(immediateCloudPush: true);
    _showInfo('$label envoyé.');
  }

  Future<void> _startChatCall(String conversationId, String callType) async {
    if (_isInLiveCall) {
      _showError('Un appel est déjà en cours.');
      return;
    }
    final targetConversationId = _resolveChatConversationId(conversationId);
    if (!_canCurrentUserPostToConversation(targetConversationId)) {
      _showError(_teamConversationAccessError());
      return;
    }
    if (targetConversationId == _teamConversationId) {
      _showError(
        'Les appels sont disponibles uniquement en conversation directe (1 à 1).',
      );
      return;
    }
    final normalizedType = callType.trim().toLowerCase() == 'video'
        ? 'video'
        : 'audio';
    final sessionId = _newId('CALL');
    final callLabel = normalizedType == 'video' ? 'vidéo' : 'audio';
    final title = targetConversationId == _teamConversationId
        ? 'Canal Équipe'
        : _conversationTitleById(targetConversationId);

    _appendChatMessage(
      ChatMessage(
        id: _newId('MSG'),
        conversationId: targetConversationId,
        senderId: _currentUser.id,
        senderName: _currentUser.name,
        text: 'Appel $callLabel entrant',
        sentAt: DateTime.now(),
        readByUserIds: [_currentUser.id],
        messageType: 'call',
        callType: normalizedType,
        callStatus: _callRingingStatus,
        callSessionId: sessionId,
      ),
    );
    _addAuditLog(
      module: 'MESSAGERIE',
      action: 'START_CALL',
      detail: 'Appel $callLabel en sonnerie ($title)',
    );
    _persistState(immediateCloudPush: true);

    // Determine callee ID from conversation for signaling metadata.
    String calleeId = '';
    if (targetConversationId.startsWith('DM|')) {
      final parts = targetConversationId.split('|');
      if (parts.length == 3) {
        calleeId = parts[1] == _currentUser.id ? parts[2] : parts[1];
      }
    }
    final callerAuthUid = _firebaseAuthUid();
    if (callerAuthUid.isEmpty) {
      _showError(
        'Session cloud indisponible. Reconnectez-vous puis réessayez.',
      );
      return;
    }
    var calleeAuthUid = '';
    if (calleeId.isNotEmpty) {
      calleeAuthUid = await _resolveAuthUidForUser(calleeId);
      if (calleeAuthUid.isEmpty) {
        _showError(
          'Le destinataire semble hors ligne sur le cloud. Réessayez quand il est connecté.',
        );
        return;
      }
    }

    int? durationSeconds;
    if (_shouldUseLiveKitTransport()) {
      final roomName = _roomNameForCallSession(sessionId);
      final service = LiveKitCallService();
      try {
        await FirebaseFirestore.instance
            .collection('porc_webrtc_signaling')
            .doc(sessionId)
            .set(<String, dynamic>{
              'callerId': _currentUser.id,
              'callerName': _currentUser.name,
              'callerAuthUid': callerAuthUid,
              'calleeId': calleeId,
              'calleeAuthUid': calleeAuthUid,
              'conversationId': targetConversationId,
              'callType': normalizedType,
              'transport': _callTransportLiveKit,
              'roomName': roomName,
              'createdAt': FieldValue.serverTimestamp(),
              'hangUp': false,
            }, SetOptions(merge: true));
        await service.connect(
          sessionId: sessionId,
          roomName: roomName,
          participantId: _currentUser.id,
          participantName: _currentUser.name,
          enableVideo: normalizedType == 'video',
        );
      } catch (e) {
        _showError('Échec appel LiveKit : $e');
        await service.dispose();
        return;
      }

      _activeLiveKitService = service;
      _activeCallSessionId = sessionId;
      if (!mounted) {
        await service.dispose();
        return;
      }
      durationSeconds = await _showLiveKitCallScreen(
        callType: normalizedType,
        title: title,
        service: service,
        sessionId: sessionId,
        isCaller: true,
      );
    } else {
      // --- WebRTC P2P fallback path ---
      final service = WebRTCCallService();
      try {
        await service.initialize(isVideo: normalizedType == 'video');
      } catch (e) {
        _showError('Échec caméra/micro : $e');
        await service.dispose();
        return;
      }
      try {
        await service.createOffer(
          sessionId,
          meta: <String, dynamic>{
            'callerId': _currentUser.id,
            'callerName': _currentUser.name,
            'callerAuthUid': callerAuthUid,
            'calleeId': calleeId,
            'calleeAuthUid': calleeAuthUid,
            'conversationId': targetConversationId,
            'callType': normalizedType,
            'transport': _callTransportWebRtc,
          },
        );
      } catch (e) {
        _showError('Échec signalisation : $e');
        await service.dispose();
        return;
      }

      _activeWebRTCService = service;
      _activeCallSessionId = sessionId;

      if (!mounted) {
        await service.dispose();
        return;
      }

      durationSeconds = await _showLiveCallScreen(
        callType: normalizedType,
        title: title,
        service: service,
        sessionId: sessionId,
        isCaller: true,
      );
    }

    // Call ended → log result
    final callStatus = durationSeconds == null ? 'Manqué' : 'Terminé';
    final callText = durationSeconds == null
        ? 'Appel $callLabel manqué'
        : 'Appel $callLabel terminé (${_formatDuration(durationSeconds)})';
    _appendChatMessage(
      ChatMessage(
        id: _newId('MSG'),
        conversationId: targetConversationId,
        senderId: _currentUser.id,
        senderName: _currentUser.name,
        text: callText,
        sentAt: DateTime.now(),
        readByUserIds: [_currentUser.id],
        messageType: 'call',
        callType: normalizedType,
        callStatus: callStatus,
        callDurationSeconds: durationSeconds ?? 0,
        callSessionId: sessionId,
      ),
    );
    _addAuditLog(
      module: 'MESSAGERIE',
      action: durationSeconds == null ? 'MISS_CALL' : 'END_CALL',
      detail: durationSeconds == null
          ? 'Appel $callLabel manqué ($title)'
          : 'Appel $callLabel terminé ($title, ${_formatDuration(durationSeconds)})',
    );
    _persistState(immediateCloudPush: true);
  }

  String _conversationTitleById(String conversationId) {
    if (conversationId == _teamConversationId) {
      return 'Canal Équipe';
    }
    for (final user in _users) {
      if (conversationId.contains(user.id) && user.id != _currentUser.id) {
        return user.name;
      }
    }
    return 'Conversation directe';
  }

  UserProfile? _peerUserForConversation(String conversationId) {
    if (!conversationId.startsWith('DM|')) {
      return null;
    }
    final parts = conversationId.split('|');
    if (parts.length != 3) {
      return null;
    }
    final first = parts[1].trim();
    final second = parts[2].trim();
    if (first == _currentUser.id) {
      return _findUserById(second);
    }
    if (second == _currentUser.id) {
      return _findUserById(first);
    }
    final firstUser = _findUserById(first);
    if (firstUser != null && firstUser.id != _currentUser.id) {
      return firstUser;
    }
    final secondUser = _findUserById(second);
    if (secondUser != null && secondUser.id != _currentUser.id) {
      return secondUser;
    }
    return null;
  }

  void _callExternalForConversation(String conversationId) {
    final peer = _peerUserForConversation(conversationId);
    if (peer == null) {
      _showError(
        'Conversation non reconnue. Impossible de déterminer le numéro externe.',
      );
      return;
    }
    _callExternalPhone(peer.contact, userName: peer.name);
  }

  String _normalizePhoneDialTarget(String rawContact) {
    final input = rawContact.trim();
    if (input.isEmpty) {
      return '';
    }
    final buffer = StringBuffer();
    var plusAdded = false;
    for (var i = 0; i < input.length; i++) {
      final char = input[i];
      final code = char.codeUnitAt(0);
      final isDigit = code >= 48 && code <= 57;
      if (isDigit) {
        buffer.write(char);
        continue;
      }
      if (char == '+' && !plusAdded && buffer.isEmpty) {
        buffer.write(char);
        plusAdded = true;
      }
    }
    final normalized = buffer.toString();
    if (normalized.startsWith('00')) {
      return '+${normalized.substring(2)}';
    }
    return normalized;
  }

  bool _isValidDialTarget(String target) {
    final digitsOnly = target.replaceAll(RegExp(r'[^0-9]'), '');
    return digitsOnly.length >= 6;
  }

  Future<void> _callExternalPhone(String rawContact, {String? userName}) async {
    final dialTarget = _normalizePhoneDialTarget(rawContact);
    if (!_isValidDialTarget(dialTarget)) {
      _showError('Numéro externe invalide ou non renseigné.');
      return;
    }
    final uri = Uri(scheme: 'tel', path: dialTarget);
    var launched = false;
    try {
      launched = await launchUrl(uri, mode: LaunchMode.platformDefault);
    } catch (_) {
      launched = false;
    }
    if (!launched) {
      _showError(
        'Impossible d\'ouvrir l\'appel téléphonique pour $dialTarget.',
      );
      return;
    }
    final targetName = _readString(userName).trim();
    final detail = targetName.isEmpty
        ? dialTarget
        : '$targetName ($dialTarget)';
    _addAuditLog(
      module: 'MESSAGERIE',
      action: 'CALL_EXTERNAL_PHONE',
      detail: 'Appel externe lancé vers $detail',
    );
    _persistState();
    _showInfo('Ouverture de l\'appel téléphonique vers $detail.');
  }

  // ignore: unused_element
  Future<int?> _showActiveCallDialog({
    required String callType,
    required String title,
    String? remoteUserId,
    String? remoteUserName,
  }) async {
    var elapsedSeconds = 0;
    Timer? ticker;
    var tickerStarted = false;
    final isVideo = callType == 'video';
    final localUser = _currentUser;
    final remoteUser = _findUserById(_readString(remoteUserId).trim());
    final trimmedRemoteName = _readString(remoteUserName).trim();
    final remoteName = trimmedRemoteName.isEmpty ? title : trimmedRemoteName;

    final result = await showDialog<int>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) {
        final maxWidth = math.min(
          MediaQuery.of(dialogContext).size.width * 0.9,
          560.0,
        );
        return StatefulBuilder(
          builder: (context, setModalState) {
            if (!tickerStarted) {
              tickerStarted = true;
              ticker = Timer.periodic(const Duration(seconds: 1), (_) {
                if (!context.mounted) {
                  ticker?.cancel();
                  return;
                }
                setModalState(() => elapsedSeconds++);
              });
            }

            return AlertDialog(
              title: Text(
                isVideo ? 'Appel vidéo en cours' : 'Appel audio en cours',
              ),
              content: SizedBox(
                width: maxWidth,
                child: isVideo
                    ? _buildActiveVideoCallContent(
                        localUser: localUser,
                        remoteUser: remoteUser,
                        remoteName: remoteName,
                        elapsedSeconds: elapsedSeconds,
                      )
                    : _buildActiveAudioCallContent(
                        title: remoteName,
                        elapsedSeconds: elapsedSeconds,
                      ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(dialogContext).pop(null),
                  child: const Text('Appel manqué'),
                ),
                FilledButton.icon(
                  onPressed: () =>
                      Navigator.of(dialogContext).pop(elapsedSeconds),
                  icon: const Icon(Icons.call_end, size: 16),
                  style: FilledButton.styleFrom(
                    backgroundColor: AppColors.error,
                    foregroundColor: Colors.white,
                  ),
                  label: const Text('Terminer'),
                ),
              ],
            );
          },
        );
      },
    );

    ticker?.cancel();
    return result;
  }

