  Widget _buildInCallVideoTile({
    required UserProfile? user,
    required String label,
    required Color accentColor,
  }) {
    final avatarLabel = _inCallAvatarLabel(user, label);
    final imageBase64 = user?.profileImageBase64.trim() ?? '';
    final imageBytes = imageBase64.isEmpty
        ? null
        : _decodeImageBytesCached(imageBase64);

    return ClipRRect(
      borderRadius: BorderRadius.circular(AppSpacing.s8),
      child: Stack(
        fit: StackFit.expand,
        children: [
          if (imageBytes != null)
            Image.memory(imageBytes, fit: BoxFit.cover)
          else
            DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [
                    accentColor.withValues(alpha: 0.85),
                    AppColors.textPrimary,
                  ],
                ),
              ),
              child: Center(
                child: CircleAvatar(
                  radius: 28,
                  backgroundColor: Colors.white.withValues(alpha: 0.2),
                  child: Text(
                    avatarLabel,
                    style: const TextStyle(
                      color: Colors.white,
                      fontWeight: FontWeight.w900,
                      fontSize: 24,
                    ),
                  ),
                ),
              ),
            ),
          Positioned(
            left: 0,
            right: 0,
            bottom: 0,
            child: Container(
              padding: const EdgeInsets.symmetric(
                horizontal: AppSpacing.s8,
                vertical: AppSpacing.s6,
              ),
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [
                    Colors.black.withValues(alpha: 0),
                    Colors.black.withValues(alpha: 0.58),
                  ],
                ),
              ),
              child: Text(
                label.trim().isEmpty ? 'Participant' : label.trim(),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.w700,
                  fontSize: 11,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  String _inCallAvatarLabel(UserProfile? user, String fallbackLabel) {
    final avatar = user?.avatar.trim() ?? '';
    if (avatar.isNotEmpty) {
      return avatar.substring(0, 1).toUpperCase();
    }
    final trimmed = fallbackLabel.trim();
    if (trimmed.isEmpty) {
      return '?';
    }
    return trimmed.substring(0, 1).toUpperCase();
  }

  String _formatDuration(int totalSeconds) {
    final safeSeconds = totalSeconds < 0 ? 0 : totalSeconds;
    final minutes = (safeSeconds ~/ 60).toString().padLeft(2, '0');
    final seconds = (safeSeconds % 60).toString().padLeft(2, '0');
    return '$minutes:$seconds';
  }

  String _normalizedCallTransportMode() {
    final mode = _callTransportMode.trim().toLowerCase();
    if (mode == _callTransportLiveKit) {
      return _callTransportLiveKit;
    }
    return _callTransportWebRtc;
  }

  bool _shouldUseLiveKitTransport() {
    return _normalizedCallTransportMode() == _callTransportLiveKit &&
        LiveKitCallService.isConfigured;
  }

  String _roomNameForCallSession(String sessionId) {
    final normalized = sessionId.trim().isEmpty ? _newId('CALL') : sessionId;
    return 'pigia_$normalized';
  }

  // ---------------------------------------------------------------------------
  // Live WebRTC call screen (fullscreen overlay)
  // ---------------------------------------------------------------------------

  /// Opens a fullscreen call screen backed by a real [WebRTCCallService].
  ///
  /// Returns the elapsed call duration in seconds, or `null` if the call was
  /// missed / never connected.
  Future<int?> _showLiveCallScreen({
    required String callType,
    required String title,
    required WebRTCCallService service,
    required String sessionId,
    required bool isCaller,
  }) async {
    _isInLiveCall = true;
    final result = await Navigator.of(context).push<int?>(
      MaterialPageRoute(
        fullscreenDialog: true,
        builder: (_) => _LiveCallPage(
          callType: callType,
          title: title,
          service: service,
          sessionId: sessionId,
          isCaller: isCaller,
        ),
      ),
    );
    _isInLiveCall = false;
    _activeWebRTCService = null;
    _activeCallSessionId = null;
    return result;
  }

  Future<int?> _showLiveKitCallScreen({
    required String callType,
    required String title,
    required LiveKitCallService service,
    required String sessionId,
    required bool isCaller,
  }) async {
    _isInLiveCall = true;
    final result = await Navigator.of(context).push<int?>(
      MaterialPageRoute(
        fullscreenDialog: true,
        builder: (_) => _LiveKitCallPage(
          callType: callType,
          title: title,
          service: service,
          sessionId: sessionId,
          isCaller: isCaller,
        ),
      ),
    );
    _isInLiveCall = false;
    _activeLiveKitService = null;
    _activeCallSessionId = null;
    return result;
  }

  String _chatMessagePreview(ChatMessage message) {
    switch (message.messageType) {
      case 'image':
        final imageName = message.mediaName.trim().isEmpty
            ? 'Image'
            : message.mediaName.trim();
        return 'Image: $imageName';
      case 'video':
        final videoName = message.mediaName.trim().isEmpty
            ? 'Vidéo'
            : message.mediaName.trim();
        return 'Vidéo: $videoName';
      case 'audio':
        final audioName = message.mediaName.trim().isEmpty
            ? 'Audio'
            : message.mediaName.trim();
        return 'Audio: $audioName';
      case 'call':
        final callLabel = message.callType == 'video'
            ? 'Appel vidéo'
            : 'Appel audio';
        final status = message.callStatus.trim().isEmpty
            ? ''
            : ' ${message.callStatus.trim()}';
        final duration = message.callDurationSeconds > 0
            ? ' (${_formatDuration(message.callDurationSeconds)})'
            : '';
        return '$callLabel$status$duration';
      default:
        final text = message.text.trim();
        return text.isEmpty ? 'Message' : text;
    }
  }

  Widget _buildChatMessageContent({
    required ChatMessage message,
    required bool isMine,
    Color? mineTextColor,
    Color? mineSubTextColor,
  }) {
    final textColor = isMine
        ? (mineTextColor ?? Colors.white)
        : AppColors.textPrimary;
    final subTextColor = isMine
        ? (mineSubTextColor ?? Colors.white70)
        : AppColors.textMuted;
    final messageType = message.messageType.trim().toLowerCase();

    if (messageType == 'image') {
      if (message.mediaBase64.trim().isEmpty) {
        return Text(
          message.text.trim().isEmpty ? 'Image indisponible.' : message.text,
          style: TextStyle(
            color: textColor,
            height: 1.35,
            fontWeight: FontWeight.w600,
          ),
        );
      }
      final bytes = _decodeImageBytesCached(message.mediaBase64);
      if (bytes != null) {
        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            if (message.text.trim().isNotEmpty &&
                message.text.trim() != 'Image envoyé')
              Padding(
                padding: const EdgeInsets.only(bottom: AppSpacing.s6),
                child: Text(
                  message.text,
                  style: TextStyle(
                    color: textColor,
                    height: 1.35,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
            ClipRRect(
              borderRadius: BorderRadius.circular(8),
              child: Image.memory(
                bytes,
                width: 220,
                height: 170,
                fit: BoxFit.cover,
              ),
            ),
            const SizedBox(height: AppSpacing.s6),
            Text(
              message.mediaName.trim().isEmpty ? 'Image' : message.mediaName,
              style: TextStyle(
                color: textColor,
                fontWeight: FontWeight.w700,
                fontSize: 12,
              ),
            ),
            if (message.mediaSizeBytes > 0)
              Text(
                _formatFileSize(message.mediaSizeBytes),
                style: TextStyle(
                  color: subTextColor,
                  fontWeight: FontWeight.w600,
                  fontSize: 11,
                ),
              ),
          ],
        );
      }
      return Text(
        'Image corrompue ou non lisible.',
        style: TextStyle(
          color: textColor,
          height: 1.35,
          fontWeight: FontWeight.w600,
        ),
      );
    }

    if (messageType == 'video' || messageType == 'audio') {
      final isVideo = messageType == 'video';
      final title = isVideo ? 'Vidéo jointe' : 'Audio joint';
      return Container(
        padding: const EdgeInsets.all(AppSpacing.s9),
        decoration: BoxDecoration(
          color: isMine
              ? Colors.white.withValues(alpha: 0.14)
              : AppColors.surfaceContainer,
          borderRadius: BorderRadius.circular(10),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              isVideo
                  ? Icons.videocam_outlined
                  : Icons.multitrack_audio_outlined,
              color: textColor,
              size: 18,
            ),
            const SizedBox(width: AppSpacing.s8),
            Flexible(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    style: TextStyle(
                      color: textColor,
                      fontWeight: FontWeight.w800,
                      fontSize: 12,
                    ),
                  ),
                  Text(
                    message.mediaName.trim().isEmpty
                        ? (isVideo ? 'video.bin' : 'audio.bin')
                        : message.mediaName,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: subTextColor,
                      fontWeight: FontWeight.w600,
                      fontSize: 11,
                    ),
                  ),
                  if (message.mediaSizeBytes > 0)
                    Text(
                      _formatFileSize(message.mediaSizeBytes),
                      style: TextStyle(
                        color: subTextColor,
                        fontWeight: FontWeight.w600,
                        fontSize: 11,
                      ),
                    ),
                ],
              ),
            ),
          ],
        ),
      );
    }

    if (messageType == 'call') {
      final isVideo = message.callType.trim().toLowerCase() == 'video';
      final callLabel = isVideo ? 'Appel vidéo' : 'Appel audio';
      final status = message.callStatus.trim().isEmpty
          ? 'Journal'
          : message.callStatus.trim();
      final canRespond =
          !isMine &&
          _isCallRingingStatus(status) &&
          _incomingCallOffer != null &&
          _incomingCallOffer!.sessionId == _callSessionIdForMessage(message);
      final duration = message.callDurationSeconds > 0
          ? ' • ${_formatDuration(message.callDurationSeconds)}'
          : '';
      final bodyText = message.text.trim().isEmpty
          ? '$callLabel $status$duration'
          : message.text.trim();

      return Container(
        padding: const EdgeInsets.all(AppSpacing.s9),
        decoration: BoxDecoration(
          color: isMine
              ? Colors.white.withValues(alpha: 0.14)
              : AppColors.surfaceContainer,
          borderRadius: BorderRadius.circular(10),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              isVideo ? Icons.videocam_outlined : Icons.call_outlined,
              color: textColor,
              size: 18,
            ),
            const SizedBox(width: AppSpacing.s8),
            Flexible(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    bodyText,
                    style: TextStyle(
                      color: textColor,
                      height: 1.25,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  Text(
                    'Statut: $status',
                    style: TextStyle(
                      color: subTextColor,
                      fontWeight: FontWeight.w600,
                      fontSize: 11,
                    ),
                  ),
                  if (canRespond) ...[
                    const SizedBox(height: AppSpacing.s6),
                    Wrap(
                      spacing: AppSpacing.s8,
                      runSpacing: AppSpacing.s6,
                      children: [
                        OutlinedButton(
                          onPressed: _rejectIncomingCallOffer,
                          child: const Text('Refuser'),
                        ),
                        FilledButton(
                          onPressed: _acceptIncomingCallOffer,
                          child: const Text('Accepter'),
                        ),
                      ],
                    ),
                  ],
                ],
              ),
            ),
          ],
        ),
      );
    }

    return Text(
      message.text,
      style: TextStyle(
        color: textColor,
        height: 1.35,
        fontWeight: FontWeight.w600,
      ),
    );
  }

  String _formatFileSize(int bytes) {
    if (bytes <= 0) {
      return '-';
    }
    if (bytes < 1024) {
      return '$bytes o';
    }
    final kb = bytes / 1024;
    if (kb < 1024) {
      return '${kb.toStringAsFixed(kb >= 100 ? 0 : 1)} KB';
    }
    final mb = kb / 1024;
    return '${mb.toStringAsFixed(mb >= 10 ? 1 : 2)} MB';
  }

  Uint8List? _decodeImageBytesCached(String base64Value) {
    final normalized = base64Value.trim();
    if (normalized.isEmpty) {
      return null;
    }

    final cached = _imageBytesCache[normalized];
    if (cached != null) {
      return cached;
    }

    try {
      final bytes = base64Decode(normalized);
      if (_imageBytesCache.length >= 220) {
        _imageBytesCache.remove(_imageBytesCache.keys.first);
      }
      _imageBytesCache[normalized] = bytes;
      return bytes;
    } catch (_) {
      return null;
    }
  }

  String _chatTimeLabel(DateTime dateTime) {
    final today = _currentDate();
    final messageDay = DateTime(dateTime.year, dateTime.month, dateTime.day);
    if (messageDay == today) {
      return DateFormat('HH:mm', 'fr_FR').format(dateTime);
    }
    if (messageDay.year == today.year) {
      return DateFormat('d MMM', 'fr_FR').format(dateTime);
    }
    return DateFormat('dd/MM/yy', 'fr_FR').format(dateTime);
  }

  String _chatClockLabel(DateTime dateTime) {
    return DateFormat('HH:mm', 'fr_FR').format(dateTime);
  }

  String _chatDayLabel(DateTime dateTime) {
    final today = _currentDate();
    final messageDay = _normalizeDate(dateTime);
    final diffDays = messageDay.difference(today).inDays;
    if (diffDays == 0) {
      return 'Aujourd\'hui';
    }
    if (diffDays == -1) {
      return 'Hier';
    }
    return DateFormat('EEEE d MMMM', 'fr_FR').format(dateTime);
  }

  String _clipText(String text, int maxChars) {
    final value = text.trim();
    if (value.length <= maxChars) {
      return value;
    }
    return '${value.substring(0, maxChars - 3)}...';
  }

  Color _roleColor(String role) {
    switch (role) {
      case Roles.admin:
        return AppColors.primaryDark;
      case Roles.inseminator:
        return AppColors.warning;
      case Roles.labTechnician:
        return AppColors.primaryDark;
      case Roles.vet:
        return const Color(0xFF15803D);
      case Roles.breeder:
      default:
        return AppColors.info;
    }
  }

  String _firstUserNameByRole(String role) {
    for (final user in _users) {
      if (user.role == role) {
        return user.name;
      }
    }
    return _adminUserProfile().name;
  }

  String _breederNameForId(String breederId) {
    if (breederId.trim().isEmpty) {
      return 'Non affecté';
    }
    return _findUserById(breederId)?.name ?? 'Éleveur inconnu';
  }

  DateTime _currentDate() {
    final now = DateTime.now();
    return DateTime(now.year, now.month, now.day);
  }

  DateTime _expectedHeatReturnDate(InseminationRecord record) {
    return record.dose1Date.add(const Duration(days: 21));
  }

  DateTime _projectedHeatReturnDate(InseminationRecord record) {
    return record.projectedReturnDate ?? _expectedHeatReturnDate(record);
  }

  DateTime _expectedPregnancyCheckDate(InseminationRecord record) {
    return record.dose1Date.add(const Duration(days: 28));
  }

  DateTime _expectedFarrowingDate(InseminationRecord record) {
    return record.dose1Date.add(const Duration(days: 114));
  }

  int? _weaningToStandingHeatIntervalDays(InseminationRecord record) {
    final weaningDate = record.weaningDate;
    final firstStanding = record.firstStandingHeatDateTime;
    if (weaningDate == null || firstStanding == null) {
      return null;
    }
    return _normalizeDate(
      firstStanding,
    ).difference(_normalizeDate(weaningDate)).inDays;
  }

  double? _oestrusDurationHours(InseminationRecord record) {
    final start = record.oestrusStartDateTime;
    final end = record.oestrusEndDateTime;
    if (start == null || end == null || end.isBefore(start)) {
      return null;
    }
    return end.difference(start).inMinutes / 60.0;
  }

  int? _returnVarianceDays(InseminationRecord record) {
    final actual = record.actualReturnDate;
    if (actual == null) {
      return null;
    }
    return _normalizeDate(
      actual,
    ).difference(_normalizeDate(_projectedHeatReturnDate(record))).inDays;
  }

  int _inseminationRecordCompletenessScore(InseminationRecord record) {
    final checks = <bool>[
      record.sowCode.trim().isNotEmpty,
      record.boarCode.trim().isNotEmpty,
      record.semenLot.trim().isNotEmpty,
      record.weaningDate != null,
      record.proestrusDateTime != null,
      record.firstStandingHeatDateTime != null,
      record.oestrusStartDateTime != null,
      record.oestrusEndDateTime != null,
      record.projectedReturnDate != null,
      record.observations.trim().isNotEmpty || record.notes.trim().isNotEmpty,
      record.inseminator.trim().isNotEmpty,
      record.dose1Date != DateTime(0),
    ];
    final done = checks.where((item) => item).length;
    return ((done / checks.length) * 100).round();
  }

  String _inseminationRecordQualityLabel(InseminationRecord record) {
    final score = _inseminationRecordCompletenessScore(record);
    final returnVariance = _returnVarianceDays(record);
    if (returnVariance != null && returnVariance.abs() >= 4) {
      return 'À vérifier';
    }
    if (score >= 85) {
      return 'Complet';
    }
    if (score >= 65) {
      return 'Partiel';
    }
    return 'Insuffisant';
  }

  Color _inseminationRecordQualityColor(InseminationRecord record) {
    final label = _inseminationRecordQualityLabel(record);
    if (label == 'Complet') {
      return const Color(0xFF15803D);
    }
    if (label == 'Partiel') {
      return const Color(0xFFB45309);
    }
    return AppColors.error;
  }

  void _changeGestationCalendarMonth(int monthDelta) {
    final nextMonth = DateTime(
      _gestationCalendarMonth.year,
      _gestationCalendarMonth.month + monthDelta,
      1,
    );
    setState(() {
      _gestationCalendarMonth = nextMonth;
      final referenceDate = _selectedGestationDate ?? nextMonth;
      final maxDay = DateTime(nextMonth.year, nextMonth.month + 1, 0).day;
      final day = math.min(referenceDate.day, maxDay);
      _selectedGestationDate = DateTime(nextMonth.year, nextMonth.month, day);
    });
    _persistState();
  }

  void _changePigletCalendarMonth(int monthDelta) {
    final nextMonth = DateTime(
      _pigletCalendarMonth.year,
      _pigletCalendarMonth.month + monthDelta,
      1,
    );
    setState(() {
      _pigletCalendarMonth = nextMonth;
      final referenceDate = _selectedPigletDate ?? nextMonth;
      final maxDay = DateTime(nextMonth.year, nextMonth.month + 1, 0).day;
      final day = math.min(referenceDate.day, maxDay);
      _selectedPigletDate = DateTime(nextMonth.year, nextMonth.month, day);
    });
    _persistState();
  }

  Map<DateTime, List<_GestationCalendarEvent>> _buildGestationCalendarEvents() {
    final events = <DateTime, List<_GestationCalendarEvent>>{};

    void addEvent({
      required DateTime date,
      required String label,
      required String type,
      required Color color,
      required IconData icon,
    }) {
      final key = _normalizeDate(date);
      final list = events.putIfAbsent(key, () => <_GestationCalendarEvent>[]);
      list.add(
        _GestationCalendarEvent(
          date: key,
          label: label,
          type: type,
          color: color,
          icon: icon,
        ),
      );
    }

    for (final record in _inseminations) {
      final pair = '${record.sowCode} x ${record.boarCode}';

      addEvent(
        date: record.dose1Date,
        label: 'IA1 $pair (lot ${record.semenLot})',
        type: 'IA',
        color: AppColors.primaryDark,
        icon: LucideIcons.syringe,
      );

      if (record.dose2Date != null) {
        addEvent(
          date: record.dose2Date!,
          label: 'IA2 $pair',
          type: 'IA',
          color: AppColors.primaryDark,
          icon: LucideIcons.syringe,
        );
      }

      if (!_isFailedStatus(record.status)) {
        addEvent(
          date: _expectedHeatReturnDate(record),
          label: 'Contrôle retour chaleur J21 - ${record.sowCode}',
          type: 'J21',
          color: const Color(0xFFB45309),
          icon: LucideIcons.badgeInfo,
        );
        addEvent(
          date: _expectedPregnancyCheckDate(record),
          label: 'Diagnostic gestation J28 - ${record.sowCode}',
          type: 'J28',
          color: const Color(0xFF0284C7),
          icon: LucideIcons.stethoscope,
        );
      }

      if (_isSuccessfulStatus(record.status)) {
        addEvent(
          date: _expectedFarrowingDate(record),
          label: 'Mise-bas prévue J114 - ${record.sowCode}',
          type: 'J114',
          color: const Color(0xFF16A34A),
          icon: LucideIcons.piggyBank,
        );
      }

      if (_isFailedStatus(record.status)) {
        addEvent(
          date: _expectedHeatReturnDate(record),
          label: 'Replanifier IA - ${record.sowCode}',
          type: 'ALERTE',
          color: AppColors.error,
          icon: LucideIcons.alertTriangle,
        );
      }
    }

    for (final record in _healthRecords) {
      if (record.nextDate == null) {
        continue;
      }
      addEvent(
        date: record.nextDate!,
        label:
            '${record.eventType} ${record.animalType} ${record.animalCode} (${record.product})',
        type: 'SANTÉ',
        color: record.eventType == 'Vaccin'
            ? const Color(0xFF15803D)
            : AppColors.warning,
        icon: record.eventType == 'Vaccin'
            ? LucideIcons.shieldCheck
            : LucideIcons.pill,
      );
    }

    for (final dayEvents in events.values) {
      dayEvents.sort((a, b) => a.label.compareTo(b.label));
    }

    return events;
  }

  Map<DateTime, List<_GestationCalendarEvent>>
  _buildPigletCareCalendarEvents() {
    final events = <DateTime, List<_GestationCalendarEvent>>{};

    void addEvent({
      required DateTime date,
      required String label,
      required String type,
      required Color color,
      required IconData icon,
    }) {
      final key = _normalizeDate(date);
      final list = events.putIfAbsent(key, () => <_GestationCalendarEvent>[]);
      list.add(
        _GestationCalendarEvent(
          date: key,
          label: label,
          type: type,
          color: color,
          icon: icon,
        ),
      );
    }

    for (final record in _pigletCareRecords) {
      addEvent(
        date: record.eventDate,
        label:
            '${record.eventType} - ${record.groupName} (${record.animalCode})',
        type: 'SOIN',
        color: AppColors.primaryDark,
        icon: LucideIcons.piggyBank,
      );

      if (record.nextDate != null) {
        addEvent(
          date: record.nextDate!,
